statement:
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under base change.

statement_tex:
\label{lemma-base-change-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under base change.

\label{lemma-projective-space-separated}
Let $S$ be a scheme.
The structure morphism $\mathbf{P}^n_S \to S$ is
\begin{enumerate}
\item separated,
\item quasi-compact,
\item satisfies the existence and uniqueness parts of the valuative criterion,
and
\item universally closed.
\end{enumerate}

\label{lemma-deform-property-fp-over-ft}
Consider a commutative diagram
$$
\xymatrix{
(\mathcal{X} \subset \mathcal{X}') \ar[rr]_{(f, f')} \ar[rd] & &
(\mathcal{Y} \subset \mathcal{Y}') \ar[ld] \\
& (\mathcal{B} \subset \mathcal{B}')
}
$$
of thickenings of algebraic stacks.
Assume $\mathcal{Y}' \to \mathcal{B}'$ locally of finite type,
$\mathcal{X}' \to \mathcal{B}'$ flat and locally of finite presentation,
$\mathcal{X} = \mathcal{B} \times_{\mathcal{B}'} \mathcal{X}'$, and
$\mathcal{Y} = \mathcal{B} \times_{\mathcal{B}'} \mathcal{Y}'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite, and
\label{item-finite-fp-over-ft}
\item add more here.
\end{enumerate}

statement:
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a gerbe, and
\item $\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is flat and locally of
finite presentation.
\end{enumerate}

statement_tex:
\label{proposition-when-gerbe}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a gerbe, and
\item $\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is flat and locally of
finite presentation.
\end{enumerate}

\label{lemma-stable-curves}
There exist an open substack $\Curvesstack^{stable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{stable}$,
\item $X \to S$ is a stable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{stable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, the genus of $X$ is $\geq 2$, and
$X$ has no rational tails or bridges,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and $\omega_{X_s}$ is ample.
\end{enumerate}
\end{enumerate}

\label{lemma-no-dense-separated-quasi-compact-open-in-qcqs}
There exists a quasi-compact and quasi-separated scheme $X$ which does
not contain a separated quasi-compact dense open.

\label{lemma-base-change-unramified}
The base change of a morphism which is unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-support}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. For an $A$-module $M$ the following are equivalent
\begin{enumerate}
\item $H^0_T(M) = M$, and
\item $\text{Supp}(M) \subset T$.
\end{enumerate}
The category of such $A$-modules is a Serre subcategory
of the category $A$-modules closed under direct sums.

statement:
The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Gorenstein}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

statement_tex:
\label{lemma-gorenstein-local-ring-fibre}
The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Gorenstein}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

\label{lemma-hilb-s-lfp}
The morphism $\Hilbfunctor_{X/B} \to B$ is separated
and locally of finite presentation.

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

statement:
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation and
$H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

statement_tex:
\label{lemma-NL-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation and
$H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-qf-and-qc-finite-fibre}
In diagram (\ref{equation-points-fibres}) the set (\ref{equation-fibre})
is finite if $f$ is of finite type and $f$ is quasi-finite at $x$.

\label{lemma-characterize-representable-quasi-compact}
Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is quasi-compact
(in the sense of Section \ref{section-representable}), and
\item for every quasi-compact algebraic space $Z$ and any morphism
$Z \to Y$ the algebraic space $Z \times_Y X$ is quasi-compact.
\end{enumerate}

\label{lemma-locally-noetherian-fibre}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces
over $S$. Let $y \in |Y|$. The following are equivalent
\begin{enumerate}
\item for some scheme $V$, point $v \in V$, and \'etale morphism $V \to Y$
mapping $v$ to $y$, the algebraic space $X_v$ is locally Noetherian,
\item for every scheme $V$, point $v \in V$, and \'etale morphism $V \to Y$
mapping $v$ to $y$, the algebraic space $X_v$ is locally Noetherian, and
\item there exists a field $k$ and a morphism $\Spec(k) \to Y$ representing
$y$ such that $X_k$ is locally Noetherian.
\end{enumerate}
If there exists a field $k_0$ and a monomorphism $\Spec(k_0) \to Y$
representing $y$, then these are also equivalent to
\begin{enumerate}
\item[(4)] the algebraic space $X_{k_0}$ is locally Noetherian.
\end{enumerate}

\label{lemma-characterize-dbcoh-proper-regular}
Let $X$ be a proper scheme over a field $k$ which is regular. Let
$K \in \Ob(D_\QCoh(\mathcal{O}_X))$. The following are equivalent
\begin{enumerate}
\item $K \in D^b_{\textit{Coh}}(\mathcal{O}_X) = D_{perf}(\mathcal{O}_X)$, and
\item $\sum_{i \in \mathbf{Z}} \dim_k \Ext^i_X(E, K) < \infty$
for all perfect $E$ in $D(\mathcal{O}_X)$.
\end{enumerate}

\label{lemma-bounded-on-fibres}
Let $f : X \to S$ be a morphism of schemes which is flat and
locally of finite presentation. Let $E$ be a pseudo-coherent
object of $D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $E$ is $S$-perfect, and
\item $E$ is locally bounded below and for every point $s \in S$
the object $L(X_s \to X)^*E$ of $D(\mathcal{O}_{X_s})$
is locally bounded below.
\end{enumerate}

\label{lemma-rig-smooth}
Let $A$ be a Noetherian ring and let $I$ be an ideal.
Let $B$ be a finite type $A$-algebra.
\begin{enumerate}
\item If $\Spec(B) \to \Spec(A)$ is smooth over $\Spec(A) \setminus V(I)$,
then $B^\wedge$ is rig-smooth over $(A, I)$.
\item If $B^\wedge$ is rig-smooth over $(A, I)$,
then there exists $g \in 1 + IB$ such that $\Spec(B_g)$ is smooth
over $\Spec(A) \setminus V(I)$.
\end{enumerate}

\label{lemma-essential-extension}
Let $R$ be a ring. Let $M \subset N$ be $R$-modules. The following
are equivalent
\begin{enumerate}
\item $M \subset N$ is an essential extension,
\item for all $x \in N$ nonzero there exists an $f \in R$ such that $fx \in M$
and $fx \not = 0$.
\end{enumerate}

\label{lemma-points-DM-locus}
Let $\mathcal{X}$ be an algebraic stack. Let $x \in |\mathcal{X}|$
correspond to $x : \Spec(k) \to \mathcal{X}$. Let $G_x/k$
be the automorphism group algebraic space of $x$. Then
\begin{enumerate}
\item  $x$ is in the DM locus of $\mathcal{X}$
if and only if $G_x \to \Spec(k)$ is unramified, and
\item $x$ is in the quasi-DM locus of $\mathcal{X}$
if and only if $G_x \to \Spec(k)$ is locally quasi-finite.
\end{enumerate}

\label{lemma-locally-quasi-finite-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally quasi-finite''
is \'etale local on the source.

\label{lemma-image-universally-closed-separated}
Let $S$ be a scheme. Let $B$ be an algebraic space over $S$.
Let $f : X \to Y$ be a surjective universally closed
morphism of algebraic spaces over $B$.
\begin{enumerate}
\item If $X$ is quasi-separated, then $Y$ is quasi-separated.
\item If $X$ is separated, then $Y$ is separated.
\item If $X$ is quasi-separated over $B$, then $Y$ is quasi-separated over $B$.
\item If $X$ is separated over $B$, then $Y$ is separated over $B$.
\end{enumerate}

\label{lemma-weird-sheaf}
There exists a sheaf of abelian groups $G$ on
$\Sch_\etale$ with the following properties
\begin{enumerate}
\item $G(\Spec(k)) = 0$ whenever $k$ is a field,
\item $G$ is limit preserving,
\item if $X \subset X'$ is a thickening, then $G(X) = G(X')$, and
\item $G$ is not zero.
\end{enumerate}

statement:
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $\mathcal{F}$ be an
$\mathcal{O}$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}$-module.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U \xrightarrow{(f_1, \ldots, f_n)}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ (f_1, \ldots, f_n)|_{U_i} = 0$.
\item Let $U$ be an object of $\mathcal{C}$ and let
$$
\mathcal{O}_U^{\oplus m} \xrightarrow{A}
\mathcal{O}_U^{\oplus n} \xrightarrow{(s_1, \ldots, s_n)}
\mathcal{F}|_U
$$
be a complex of $\mathcal{O}_U$-modules. Then there exists a covering
$\{U_i \to U\}$ and for each $i$ a factorization
$$
\mathcal{O}_{U_i}^{\oplus n}
\xrightarrow{B_i}
\mathcal{O}_{U_i}^{\oplus l_i} \xrightarrow{(t_{i1}, \ldots, t_{il_i})}
\mathcal{F}|_{U_i}
$$
of $(s_1, \ldots, s_n)|_{U_i}$ such that
$B_i \circ A|_{U_i} = 0$.
\end{enumerate}

statement_tex:
