\label{lemma-local-isomorphism-permanence}
Let $A$ be a ring. Let $B \to C$ be an $A$-algebra homomorphism.
\begin{enumerate}
\item If $A \to B$ and $A \to C$ are local isomorphisms, then $B \to C$
is a local isomorphism.
\item If $A \to B$ and $A \to C$ identify local rings, then $B \to C$
identifies local rings.
\end{enumerate}

\label{lemma-descending-property-finite}
The property $\mathcal{P}(f) =$``$f$ is finite''
is fpqc local on the base.

\label{lemma-characterize-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is formally \'etale,
\item $f$ is formally unramified and the universal first order thickening
of $X$ over $S$ is equal to $X$,
\item $f$ is formally unramified and $\mathcal{C}_{X/S} = 0$, and
\item $\Omega_{X/S} = 0$ and $\mathcal{C}_{X/S} = 0$.
\end{enumerate}

\label{lemma-check-immersion-covering}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Let $W$ be an algebraic space and let $W \to \mathcal{Y}$ be a surjective,
flat morphism which is locally of finite presentation. The following
are equivalent:
\begin{enumerate}
\item $f$ is an (open, resp.\ closed) immersion, and
\item $V = W \times_\mathcal{Y} \mathcal{X}$ is an algebraic space, and
$V \to W$ is an (open, resp.\ closed) immersion.
\end{enumerate}

