\begin{enumerate}
\item If $A \to B$ factors as $A \to A_f \to B$ for some $f \in A$,
then $\omega_{B/A} = \omega_{B/A_f}$.
\item If $g \in B$, then $(\omega_{B/A})_g = \omega_{B_g/A}$.
\item If $f \in A$, then $\omega_{B_f/A_f} = (\omega_{B/A})_f$.
\end{enumerate}

\label{lemma-NL-formally-smooth}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item $H^{-1}(\NL_{X/Y}) = 0$ and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is locally projective.
\end{enumerate}

\label{lemma-equivalence-h-v-locally-finite-presentation}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms
of schemes with fixed target with $f_i$ locally of finite
presentation for all $i$. The following are equivalent
\begin{enumerate}
\item $\{X_i \to X\}$ is a ph covering, and
\item $\{X_i \to X\}$ is a V covering.
\end{enumerate}

\label{lemma-schemes-RS}
Example \ref{example-schemes}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any scheme $X$ over $k$.

\label{lemma-Noetherian-adic-finite-type-red}
Let $\varphi : A \to B$ be an arrow of $\textit{WAdm}^{Noeth}$.
If $\varphi$ is adic the following are equivalent
\begin{enumerate}
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type-red} and
\item $\varphi$ satisfies the condition defined in
Lemma \ref{lemma-finite-type}.
\end{enumerate}

statement:
There exist an open substack $\Curvesstack^{CM, 1} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item the morphism $X \to S$ is Cohen-Macaulay and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM, 1}$,
\item $X$ is Cohen-Macaulay and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

