statement:
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is unramified over $S$, then $f$ is unramified.
\item If $X$ is G-unramified over $S$ and $Y$ is locally of finite type
over $S$, then $f$ is G-unramified.
\end{enumerate}

statement_tex:
\label{lemma-unramified-permanence}
Let $f : X \to Y$ be a morphism of schemes over $S$.
\begin{enumerate}
\item If $X$ is unramified over $S$, then $f$ is unramified.
\item If $X$ is G-unramified over $S$ and $Y$ is locally of finite type
over $S$, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-locally-closed-where-H0-locally-free}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subspace $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$ if and only if
for all morphisms $g : Y' \to Y$ the $\mathcal{O}_{Y'}$-module
$H^a(L(f \circ g)^*E)$ is locally free of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in |X|$, then $j$ is
a closed immersion and given $f : Y \to X$ the following are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^0(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^0(Lf^*E), H^0(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}

\label{lemma-F-zero-module-map}
Let $A$ be a ring. Let $u : M \to N$ be a map of $A$-modules.
If $N$ is projective as an $A$-module, then there exists an ideal
$I \subset A$ such that for any ring map $\varphi : A \to B$
the following are equivalent
\begin{enumerate}
\item $u \otimes 1 : M \otimes_A B \to N \otimes_A B$ is zero, and
\item $\varphi(I) = 0$.
\end{enumerate}

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
schemes is (universally) submersive.

\label{lemma-zariski-etale-smooth-syntomic-fppf-fpqc}
Any fppf covering is an fpqc covering, and a fortiori,
any syntomic, smooth, \'etale or Zariski covering is an fpqc covering.

\label{lemma-bounded-truncation}
Let $S$ be a scheme.
Let $X$ be a quasi-compact and quasi-separated algebraic space over $S$.
Let $P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \gg 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\geq a} E) = 0$ for $i \gg 0$.
\end{enumerate}

statement:
\begin{reference}
\cite[Proposition 7.5.5]{EGA1}
\end{reference}
Let $A$ be a Noetherian ring and let $I \subset A$ be an ideal. Then
\begin{enumerate}
\item every object of the category $\mathcal{C}'$
(\ref{equation-C-prime}) is Noetherian,
\item if $B \in \Ob(\mathcal{C}')$ and $J \subset B$ is an ideal,
then $B/J$ is an object of $\mathcal{C}'$,
\item for a finite type $A$-algebra $C$ the $I$-adic completion
$C^\wedge$ is in $\mathcal{C}'$,
\item in particular the completion $A[x_1, \ldots, x_r]^\wedge$
is in $\mathcal{C}'$.
\end{enumerate}

