\label{lemma-perfect-reduced}
Let $X$ be an algebraic space over a perfect field $k$ (for example
$k$ has characteristic zero).
\begin{enumerate}
\item For $x \in |X|$, if $\mathcal{O}_{X, \overline{x}}$ is
reduced, then $X$ is geometrically reduced at $x$.
\item If $X$ is reduced, then $X$ is geometrically reduced over $k$.
\end{enumerate}

\label{lemma-descending-property-formally-smooth}
The property $\mathcal{P}(f) =$``$f$ is formally smooth''
is fpqc local on the base.

\label{lemma-when-universally-injective-radicial}
Let $S$ be a scheme. Let $f : X \to Y$ be a universally injective
morphism of algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is decent then $f$ is radicial.
\item If $f$ is quasi-separated then $f$ is radicial.
\item If $f$ is locally separated then $f$ is radicial.
\end{enumerate}

\label{lemma-proper-pure}
Let $f : X \to S$ be a morphism of schemes which is of finite type.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If the support of $\mathcal{F}$ is proper over $S$, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then
$\mathcal{F}$ is universally pure relative to $S$.
\item If $f$ is proper, then $X$ is universally pure relative to $S$.
\end{enumerate}

\label{lemma-characterize-representable-universally-submersive}
Let $S$ be a scheme. Let $f : X \to Y$ be a representable morphism of
algebraic spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is universally submersive
(in the sense of Section \ref{section-representable}), and
\item for every morphism of algebraic spaces $Z \to Y$ the morphism of
topological spaces $|Z \times_Y X| \to |Z|$ is submersive.
\end{enumerate}

\label{lemma-unramified-flat-lfp-etale}
A locally finitely presented, flat, unramified morphism of algebraic
spaces is \'etale.

\label{lemma-describe-functoriality}
Let $f : Y \to X$ be a morphism of simplicial spaces. In terms of the
description of sheaves in
Lemma \ref{lemma-describe-sheaves-simplicial-site} the
morphism $f_{Zar}$ of Lemma \ref{lemma-simplicial-space-site-functorial}
can be described as follows.
\begin{enumerate}
\item If $\mathcal{G}$ is a sheaf on $Y$, then
$(f_{Zar, *}\mathcal{G})_n = f_{n, *}\mathcal{G}_n$.
\item If $\mathcal{F}$ is a sheaf on $X$, then
$(f_{Zar}^{-1}\mathcal{F})_n = f_n^{-1}\mathcal{F}_n$.
\end{enumerate}

