\label{lemma-make-commute-map}
Let $(A, \text{d})$ be a differential graded algebra. Let
$$
\xymatrix{
K \ar[r]_f \ar[d]_a & L \ar[d]^b \\
M \ar[r]^g & N
}
$$
be a diagram of homomorphisms of differential graded $A$-modules
commuting up to homotopy.
\begin{enumerate}
\item If $f$ is an admissible monomorphism, then $b$ is homotopic to a
homomorphism which makes the diagram commute.
\item If $g$ is an admissible epimorphism, then $a$ is homotopic to a
morphism which makes the diagram commute.
\end{enumerate}

\label{lemma-noetherian-finite-type-finite-presentation}
\begin{slogan}
Over a locally Noetherian base, finite type is finite presentation.
\end{slogan}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $S$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $S$ is locally Noetherian and $f$ of finite type
then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-approximate-by-etale-over-complement}
Let $A$ be a Noetherian ring. Let $I \subset A$ be an ideal.
Let $B$ be an $I$-adically complete $A$-algebra with $A/I \to B/IB$
of finite type. The equivalent conditions of
Lemma \ref{lemma-equivalent-with-artin} are also equivalent to
\begin{enumerate}
\item[(8)]
\label{item-algebraize}
there exists a finite type $A$-algebra $C$ such that
$\Spec(C) \to \Spec(A)$ is \'etale over $\Spec(A) \setminus V(I)$
and such that $B \cong C^\wedge$.
\end{enumerate}

\label{lemma-finite-finitely-presented-over-w-contractible}
Let $A \to B$ be a finite and finitely presented ring map.
If $A$ is w-contractible, so is $B$.

\label{lemma-characterize-minimal-groupoid-in-functors}
Let $(U, R, s, t, c)$ be a smooth prorepresentable groupoid in
functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is normalized if and only if the morphism
$U \to [U/R]$ induces an isomorphism on tangent spaces, and
\item $(U, R, s, t, c)$ is minimal if and only if the kernel of
$TU \to T[U/R]$ is contained in the image of
$\text{Der}_\Lambda(k, k) \to TU$.
\end{enumerate}

\label{lemma-rickard}
Let $R$ be a ring. Let $(A, \text{d})$ and $(B, \text{d})$ be
differential graded $R$-algebras. Assume that $A = H^0(A)$.
The following are equivalent
\begin{enumerate}
\item $D(A, \text{d})$ and $D(B, \text{d})$ are equivalent as $R$-linear
triangulated categories, and
\item there exists an object $P$ of $D(B, \text{d})$ such that
\begin{enumerate}
\item $P$ is a compact object of $D(B, \text{d})$,
\item if $N \in D(B, \text{d})$ with $\Hom_{D(B, \text{d})}(P, N[i]) = 0$
for $i \in \mathbf{Z}$, then $N = 0$,
\item $\Hom_{D(B, \text{d})}(P, P[i]) = 0$ for $i \not = 0$ and
equal to $A$ for $i = 0$.
\end{enumerate}
\end{enumerate}
The equivalence $D(A, \text{d}) \to D(B, \text{d})$
constructed in (2) sends $A$ to $P$.

\label{lemma-relative-pseudo-coherent-is-moot}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of
algebraic spaces over $S$. Let $E$ in $D_\QCoh(\mathcal{O}_X)$.
If $f$ is flat and locally of finite presentation, then
the following are equivalent
\begin{enumerate}
\item $E$ is pseudo-coherent relative to $Y$, and
\item $E$ is pseudo-coherent on $X$.
\end{enumerate}

\label{lemma-composition-regular-immersion}
Let $S$ be a scheme. Let $i : Z \to Y$ and $j : Y \to X$ be immersions of
algebraic spaces over $S$.
\begin{enumerate}
\item If $i$ and $j$ are Koszul-regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are $H_1$-regular immersions, so is $j \circ i$.
\item If $i$ is an $H_1$-regular immersion and $j$ is a quasi-regular
immersion, then $j \circ i$ is a quasi-regular immersion.
\end{enumerate}

\label{lemma-composition-unramified}
The composition of two morphisms which are unramified is unramified.
The same holds for G-unramified morphisms.

\label{lemma-good}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$.
The following are equivalent
\begin{enumerate}
\item there exists a proper smooth model for $C$,
\item there exists a minimal model for $C$ which is smooth over $R$,
\item any minimal model is smooth over $R$.
\end{enumerate}

\label{lemma-characterize-regular}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is regular,
\item $X$ is locally Noetherian and all of its local rings are regular,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is regular.
\end{enumerate}

\label{lemma-zero-dimensional-flat-ideal}
\begin{slogan}
Zero dimensional ring with flat ideal.
\end{slogan}
There exists a local ring $R$ with a unique prime ideal
and a nonzero ideal $I \subset R$ which is a flat $R$-module

\label{proposition-positivity}
\begin{reference}
This is one of the main results of \cite{Serre_algebre_locale}.
\end{reference}
Let $X$ be a nonsingular variety. Let $V \subset X$ and
$W \subset Y$ be closed subvarieties which intersect properly.
Let $Z \subset V \cap W$ be an irreducible component.
Then $e(X, V \cdot W, Z) > 0$.

\label{lemma-not-essentially-surjective}
The canonical map $\mathcal{X}(S) \to \lim \mathcal{X}(S_n)$
is not essentially surjective.

\label{lemma-check-smoothness-on-infinitesimal-nbhds}
Let $f : X \to S$ be a finite type morphism of locally Noetherian schemes.
Let $Z \subset S$ be a closed subscheme with $n$th infinitesimal
neighbourhood $Z_n \subset S$. Set $X_n = Z_n \times_S X$.
\begin{enumerate}
\item If $X_n \to Z_n$ is smooth for all $n$, then $f$
is smooth at every point of $f^{-1}(Z)$.
\item If $X_n \to Z_n$ is \'etale for all $n$, then $f$
is \'etale at every point of $f^{-1}(Z)$.
\end{enumerate}

