\item the morphism $X \to S$ is Gorenstein,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item $X$ is Gorenstein.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-gorenstein-curves}
There exist an open substack $\Curvesstack^{Gorenstein} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item the morphism $X \to S$ is Gorenstein,
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein}$,
\item $X$ is Gorenstein.
\end{enumerate}
\end{enumerate}

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of schemes
by any morphism of schemes is universally submersive.

\label{lemma-cohomology-of-open}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $U$ be an object of $\mathcal{C}$.
\begin{enumerate}
\item If $\mathcal{I}$ is an injective $\mathcal{O}$-module
then $\mathcal{I}|_U$ is an injective $\mathcal{O}_U$-module.
\item For any sheaf of $\mathcal{O}$-modules $\mathcal{F}$ we have
$H^p(U, \mathcal{F}) = H^p(\mathcal{C}/U, \mathcal{F}|_U)$.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces over
$S$. The following are equivalent
\begin{enumerate}
\item $f$ is flat and perfect, and
\item $f$ is flat and locally of finite presentation.
\end{enumerate}

statement_tex:
\label{lemma-flat-finite-presentation-perfect}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces over
$S$. The following are equivalent
\begin{enumerate}
\item $f$ is flat and perfect, and
\item $f$ is flat and locally of finite presentation.
\end{enumerate}

\label{lemma-geometrically-reduced-at-point}
Let $k$ be a field. Let $X$ be an algebraic space over $k$.
Let $x \in |X|$. The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced at $x$,
\item for some \'etale neighbourhood $(U, u) \to (X, x)$
where $U$ is a scheme, $U$ is geometrically reduced at $u$,
\item for any \'etale neighbourhood $(U, u) \to (X, x)$
where $U$ is a scheme, $U$ is geometrically reduced at $u$.
\end{enumerate}

\label{lemma-unique-point-better}
Let $S$ be a scheme. Let $Z$ be an algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $Z$ is reduced, locally Noetherian, and $|Z|$
is a singleton, and
\item there exists a locally finitely presented, surjective, flat morphism
$\Spec(k) \to Z$ where $k$ is a field.
\end{enumerate}

\label{lemma-semistable}
Let $f : X \to S$ be a prestable family of curves of genus $g \geq 1$.
Let $s \in S$ be a point of the base scheme. Let $m \geq 2$.
The following are equivalent
\begin{enumerate}
\item $X_s$ does not have a rational tail
(Algebraic Curves, Example \ref{curves-example-rational-tail}), and
\item $f^*f_*\omega_{X/S}^{\otimes m} \to \omega_{X/S}^{\otimes m}$,
is surjective over $f^{-1}(U)$ for some $s \in U \subset S$ open.
\end{enumerate}

\label{lemma-finite-flat-is-finite-locally-free}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item every finite flat quasi-coherent $\mathcal{O}_X$-module is
finite locally free, and
\item every closed subset $Z \subset X$ which is closed under generalizations
is open.
\end{enumerate}

\label{lemma-vanishing-universally-closed}
In Cohomology of Spaces, Situation \ref{spaces-cohomology-situation-vanishing}
the morphism $p : X \to \Spec(A)$ is universally closed.

\label{lemma-self-centralizing-subfield}
Let $A$ be a finite central simple algebra over $k$.
If $K \subset A$ is a subfield, then the following are equivalent
\begin{enumerate}
\item $[A : k] = [K : k]^2$,
\item $K$ is its own centralizer, and
\item $K$ is a maximal commutative subring.
\end{enumerate}

\label{lemma-UR-quasi-compact-above-x}
Let $\mathcal{X}$ be an algebraic stack. Let $x \in |\mathcal{X}|$
be a point. The following are equivalent
\begin{enumerate}
\item some morphism $\Spec(k) \to \mathcal{X}$ in the equivalence
class of $x$ is quasi-compact, and
\item any morphism $\Spec(k) \to \mathcal{X}$ in the equivalence
class of $x$ is quasi-compact.
\end{enumerate}

\label{lemma-zariski-etale-smooth-syntomic}
Any smooth covering is a syntomic covering, and a fortiori,
any \'etale or Zariski covering is a syntomic covering.

statement:
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible,
\item every faithfully flat, ind-\'etale ring map $A \to B$ has
a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local,
\item $\pi_0(\Spec(A))$ is extremally disconnected, and
\item for every maximal ideal $\mathfrak m \subset A$ the
local ring $A_\mathfrak m$ is strictly henselian.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-w-local-strictly-henselian-extremally-disconnected}
Let $A$ be a ring. The following are equivalent
\begin{enumerate}
\item $A$ is w-contractible,
\item every faithfully flat, ind-\'etale ring map $A \to B$ has
a retraction, and
\item $A$ satisfies
\begin{enumerate}
\item $\Spec(A)$ is w-local,
\item $\pi_0(\Spec(A))$ is extremally disconnected, and
\item for every maximal ideal $\mathfrak m \subset A$ the
local ring $A_\mathfrak m$ is strictly henselian.
\end{enumerate}
\end{enumerate}

\label{lemma-set-iso-classes-bounded-size}
Let $\mathcal{A}$ be a Grothendieck abelian category with generator $U$.
\begin{enumerate}
\item If $|M| \leq \kappa$, then $M$ is the quotient of a direct
sum of at most $\kappa$ copies of $U$.
\item For every cardinal $\kappa$ the isomorphism classes
of objects $M$ with $|M| \leq \kappa$ form a set.
\end{enumerate}

\label{lemma-tensor-coherent}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $\mathcal{F}$ and $\mathcal{G}$ are coherent $\mathcal{O}_X$-modules,
then $\text{Tor}_p^{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ is too.
\item If $L$ and $K$ are in $D^-_{\textit{Coh}}(\mathcal{O}_X)$, then
so is $L \otimes_{\mathcal{O}_X}^\mathbf{L} K$.
\end{enumerate}

\label{theorem-bondal-van-den-Bergh}
Let $X$ be a quasi-compact and quasi-separated scheme. The category
$D_\QCoh(\mathcal{O}_X)$ can be generated by a single
perfect object. More precisely, there exists a perfect object
$P$ of $D(\mathcal{O}_X)$ such that for 
$E \in D_\QCoh(\mathcal{O}_X)$ the following are equivalent
\begin{enumerate}
\item $E = 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[n], E) = 0$ for all $n \in \mathbf{Z}$.
\end{enumerate}

\label{lemma-base-change-etale}
The base change of an \'etale morphism of algebraic spaces
by any morphism of algebraic spaces is \'etale.

\label{lemma-bounded-below-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme. Let
$P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$.
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \ll 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\leq a} E) = 0$ for $i \ll 0$.
\end{enumerate}

\label{lemma-noether-different-product}
Let $A \to B_i$, $i = 1, 2$ be ring maps. Set $B = B_1 \times B_2$.
\begin{enumerate}
\item The annihilator $J$ of $\Ker(B \otimes_A B \to B)$ is $J_1 \times J_2$
where $J_i$ is the annihilator of $\Ker(B_i \otimes_A B_i \to B_i)$.
\item The Noether different $\mathfrak{D}$ of $B$ over $A$ is
$\mathfrak{D}_1 \times \mathfrak{D}_2$, where $\mathfrak{D}_i$ is
the Noether different of $B_i$ over $A$.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
Let $x \in |X|$ be a closed point such that $U = X \setminus \{x\} \to X$
is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}^h) \setminus \{\mathfrak m_x^h\}$
the base change functor
$$
\left\{
\begin{matrix}
f : Y \to X\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{X, x}^h)\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

statement_tex:
\label{lemma-modifications}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
Let $x \in |X|$ be a closed point such that $U = X \setminus \{x\} \to X$
is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}^h) \setminus \{\mathfrak m_x^h\}$
the base change functor
$$
\left\{
\begin{matrix}
f : Y \to X\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{X, x}^h)\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{lemma-lci-gorenstein}
A syntomic morphism is Gorenstein. Equivalently a flat
local complete intersection morphism is Gorenstein.

\label{lemma-finite-presentation-finite-type}
A morphism which is locally of finite presentation is locally of finite type.
A morphism of finite presentation is of finite type.

\label{lemma-descent-ascent}
Let $f : X \to Y$ be a morphism of locally Noetherian schemes. Assume
\begin{enumerate}
\item $f$ is syntomic and surjective, or
\item $f$ is a surjective flat local complete intersection morphism, or
\item $f$ is a surjective Gorenstein morphism of finite type.
\end{enumerate}
Then $K \in D_\QCoh(\mathcal{O}_Y)$ is a dualizing complex on $Y$ if and only
if $Lf^*K$ is a dualizing complex on $X$.

\label{lemma-base-change-flat}
Let $S$ be a scheme. Let $f : X \to Y$ and $g : Z \to Y$
be morphisms of locally Noetherian formal algebraic spaces over $S$.
\begin{enumerate}
\item If $f$ is flat and $g_{red} : Z_{red} \to Y_{red}$ is
locally of finite type, then the base change
$X \times_Y Z \to Z$ is flat.
\item If $f$ is flat and locally of finite type, then
the base change $X \times_Y Z \to Z$ is flat and locally of finite type.
\end{enumerate}

\label{lemma-colimits-flat}
Colimits and tensor product.
\begin{enumerate}
\item A filtered colimit of flat presheaves of modules
is flat. A direct sum of flat presheaves of modules is flat.
\item A filtered colimit of flat sheaves of modules is flat.
A direct sum of flat sheaves of modules is flat.
\end{enumerate}

\label{lemma-check-finiteness-local-cohomology-by-annihilator-complex}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $K$ be an object of $D_{\textit{Coh}}^+(A)$.
Let $n \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $H^i_T(K)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(K)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(K)$ for $i \leq n$.
\end{enumerate}

\label{lemma-descending-property-universal-homeomorphism}
The property $\mathcal{P}(f) =$``$f$ is a universal homeomorphism''
is fpqc local on the base.

statement:
\begin{reference}
Our proof follows closely the proof given in \cite[Theorem 1.2.2]{CLO}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated algebraic space over
$\Spec(\mathbf{Z})$. There exist a directed set $I$
and an inverse system of algebraic spaces $(X_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $X_i$ is quasi-separated and of finite type over
$\mathbf{Z}$, and
\item $X = \lim X_i$.
\end{enumerate}

statement_tex:
\label{proposition-approximate}
\begin{reference}
Our proof follows closely the proof given in \cite[Theorem 1.2.2]{CLO}.
\end{reference}
Let $X$ be a quasi-compact and quasi-separated algebraic space over
$\Spec(\mathbf{Z})$. There exist a directed set $I$
and an inverse system of algebraic spaces $(X_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $X_i$ is quasi-separated and of finite type over
$\mathbf{Z}$, and
\item $X = \lim X_i$.
\end{enumerate}

\label{proposition-smooth-covering-compute-direct-image}
Let $f : \mathcal{U} \to \mathcal{X}$ and $g : \mathcal{X} \to \mathcal{Y}$
be composable $1$-morphisms of algebraic stacks.
\begin{enumerate}
\item Assume that $f$ is representable by algebraic spaces, surjective and
smooth.
\begin{enumerate}
\item If $\mathcal{F}$ is in $\textit{Ab}(\mathcal{X}_\etale)$
then there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Ab}(\mathcal{Y}_\etale)$ with higher direct images
computed in the \'etale topology.
\item If $\mathcal{F}$ is in
$\textit{Mod}(\mathcal{X}_\etale, \mathcal{O}_\mathcal{X})$ then
there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Mod}(\mathcal{Y}_\etale, \mathcal{O}_\mathcal{Y})$.
\end{enumerate}
\item Assume that $f$ is representable by algebraic spaces, surjective,
flat, and locally of finite presentation.
\begin{enumerate}
\item If $\mathcal{F}$ is in $\textit{Ab}(\mathcal{X})$ then there is
a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Ab}(\mathcal{Y})$ with higher direct images
computed in the fppf topology.
\item If $\mathcal{F}$ is in $\textit{Mod}(\mathcal{O}_\mathcal{X})$ then
there is a spectral sequence
$$
E_1^{p, q} = R^q(g \circ f_p)_*f_p^{-1}\mathcal{F}
\Rightarrow
R^{p + q}g_*\mathcal{F}
$$
in $\textit{Mod}(\mathcal{O}_\mathcal{Y})$.
\end{enumerate}
\end{enumerate}

\label{lemma-functoriality-galois-normal}
In diagram (\ref{equation-translation}) the following are equivalent
\begin{enumerate}
\item the image of $h'$ is normal, and
\item for every connected object $X'$ of $\mathcal{C}'$ such that
there is a morphism from the final object of $\mathcal{C}''$
to $H'(X')$ we have that $H'(X')$ is isomorphic to a finite coproduct
of final objects.
\end{enumerate}

\label{lemma-formal-smoothness-representable}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is formally smooth,
\item for every scheme $T$ and morphism $T \to \mathcal{Y}$
the morphism $\mathcal{X} \times_\mathcal{Y} T \to T$
is formally smooth as a morphism of algebraic spaces.
\end{enumerate}

\label{lemma-pre-genus-in-CM-1}
We have $\Curvesstack^{h0, 1} \subset \Curvesstack^{CM, 1}$
as open substacks of $\Curvesstack$.

\label{lemma-ubiquity-uc}
The following types of schemes are universally catenary.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Cohen-Macaulay scheme.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a $1$-dimensional
Noetherian domain.
\item And so on.
\end{enumerate}

statement:
Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
is sharp in the sense that one can neither drop the assumption
of quasi-compactness nor the assumption of quasi-separatedness.

statement_tex:
\label{lemma-pushforward-quasi-coherent}
Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
is sharp in the sense that one can neither drop the assumption
of quasi-compactness nor the assumption of quasi-separatedness.

\label{lemma-quasi-separated-very-reasonable}
An algebraic space which is Zariski locally quasi-separated is very reasonable.
In particular any quasi-separated algebraic space is very reasonable.

statement:
Let $j : \mathcal{X} \to \mathcal{Y}$ be an immersion of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{Y}$ is locally Noetherian, then
$\mathcal{X}$ is locally Noetherian and $j$ is quasi-compact.
\item If $\mathcal{Y}$ is Noetherian, then $\mathcal{X}$ is Noetherian.
\end{enumerate}

statement_tex:
\label{lemma-locally-closed-in-noetherian}
Let $j : \mathcal{X} \to \mathcal{Y}$ be an immersion of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{Y}$ is locally Noetherian, then
$\mathcal{X}$ is locally Noetherian and $j$ is quasi-compact.
\item If $\mathcal{Y}$ is Noetherian, then $\mathcal{X}$ is Noetherian.
\end{enumerate}

\label{lemma-syntomic-syntomic-local-source}
The property $\mathcal{P}(f)=$``$f$ is syntomic''
is syntomic local on the source.

\label{lemma-affine-jacobson}
An affine scheme $\Spec(R)$ is Jacobson if and only if
the ring $R$ is Jacobson.

\label{lemma-deform-property-fp-over-ft}
Let $S$ be a scheme. Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (B \subset B')
}
$$
of thickenings of algebraic spaces over $S$.
Assume $Y' \to B'$ locally of finite type,
$X' \to B'$ flat and locally of finite presentation,
$X = B \times_{B'} X'$, and $Y = B \times_{B'} Y'$. Then
\begin{enumerate}
\item $f$ is representable if and only if $f'$ is representable,
\label{item-representable-fp-over-ft}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact-fp-over-ft}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed-fp-over-ft}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective-fp-over-ft}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective-fp-over-ft}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item
\label{item-relative-dimension-d-fp-over-ft}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite-fp-over-ft}
\item
\label{item-finite-locally-free-fp-over-ft}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-sheaf-property-fpqc}
Let $F$ be a contravariant functor on the category
of schemes with values in sets. Then $F$ satisfies
the sheaf property for the fpqc topology if and only
if it satisfies
\begin{enumerate}
\item the sheaf property for every Zariski covering, and
\item the sheaf property for any standard fpqc covering.
\end{enumerate}
Moreover, in the presence of (1) property (2) is equivalent to
property
\begin{enumerate}
\item[(2')] the sheaf property for $\{V \to U\}$
with $V$, $U$ affine and $V \to U$ faithfully flat.
\end{enumerate}

\label{lemma-coherent-diagonal-affine-fp}
The diagonal of $\Cohstack_{X/B}$ over $B$ is affine
and of finite presentation.

statement:
\begin{reference}
\cite{CLO}
\end{reference}
Let $S$ be a scheme. Let $B$ be a quasi-compact and quasi-separated
algebraic space over $S$. Let $X \to B$ be a separated, finite type morphism.
Then $X$ has a compactification over $B$.

statement_tex:
\label{theorem-nagata}
\begin{reference}
\cite{CLO}
\end{reference}
Let $S$ be a scheme. Let $B$ be a quasi-compact and quasi-separated
algebraic space over $S$. Let $X \to B$ be a separated, finite type morphism.
Then $X$ has a compactification over $B$.

\label{lemma-characterize-etale}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is \'etale, and
\item $f$ is locally of finite presentation, flat, and unramified,
\item $f$ is locally of finite presentation, flat, and its diagonal
is \'etale.
\end{enumerate}

statement:
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is universally catenary, and
\item all local rings $\mathcal{O}_{S, s}$ of $S$ are universally catenary.
\end{enumerate}

statement_tex:
\label{lemma-universally-catenary-local-rings-universally-catenary}
Let $S$ be a locally Noetherian scheme.
The following are equivalent:
\begin{enumerate}
\item $S$ is universally catenary, and
\item all local rings $\mathcal{O}_{S, s}$ of $S$ are universally catenary.
\end{enumerate}

\label{lemma-base-change-integral}
The base change of an integral (resp.\ finite) morphism is integral
(resp.\ finite).

\label{lemma-flat-up-down-henselization}
Let $S$ be a scheme and $s \in S$ a point. Denote $\mathcal{O}_{S, s}^h$
(resp.\ $\mathcal{O}_{S, s}^{sh}$) the henselization (resp.\ strict
henselization), see
Algebra, Definition \ref{algebra-definition-henselization}.
Let $M^{sh}$ be a $\mathcal{O}_{S, s}^{sh}$-module.
The following are equivalent
\begin{enumerate}
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}$,
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^h$, and
\item $M^{sh}$ is flat over $\mathcal{O}_{S, s}^{sh}$.
\end{enumerate}
If $M^{sh} = M^h \otimes_{\mathcal{O}_{S, s}^h} \mathcal{O}_{S, s}^{sh}$
this is also equivalent to
\begin{enumerate}
\item[(4)] $M^h$ is flat over $\mathcal{O}_{S, s}$, and
\item[(5)] $M^h$ is flat over $\mathcal{O}_{S, s}^h$.
\end{enumerate}
If $M^h = M \otimes_{\mathcal{O}_{S, s}} \mathcal{O}_{S, s}^h$
this is also equivalent to
\begin{enumerate}
\item[(6)] $M$ is flat over $\mathcal{O}_{S, s}$.
\end{enumerate}

\label{lemma-descending-property-isomorphism}
The property $\mathcal{P}(f) =$``$f$ is an isomorphism''
is fpqc local on the base.

\label{lemma-representable-sheaf-fpqc}
Any representable presheaf on $\Sch/S$ satisfies the
sheaf condition for the fpqc topology.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{lemma-coherent-qs-lfp}
The morphism $\Cohstack_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-tor-dimension-affine}
Let $X = \Spec(A)$ be an affine scheme. Let $M^\bullet$ be a
complex of $A$-modules and let $E$ be the corresponding object
of $D(\mathcal{O}_X)$. Then
\begin{enumerate}
\item $E$ has tor amplitude in $[a, b]$ if and only if $M^\bullet$
has tor amplitude in $[a, b]$.
\item $E$ has finite tor dimension if and only if $M^\bullet$
has finite tor dimension.
\end{enumerate}

\label{lemma-Weierstrass-smooth-cover}
The morphism $W \xrightarrow{(E_W, f_W, 0_W)} \mathcal{M}_{1, 1}$ is smooth
and surjective.

statement:
\begin{reference}
\cite[Theorem on page 151]{Lipman}
\end{reference}
Let $Y$ be a two dimensional integral Noetherian scheme. The following are
equivalent
\begin{enumerate}
\item there exists an alteration $X \to Y$ with $X$ regular,
\item there exists a resolution of singularities of $Y$,
\item $Y$ has a resolution of singularities by normalized blowups,
\item the normalization $Y^\nu \to Y$ is finite, $Y^\nu$ has
finitely many singular points $y_1, \ldots, y_m$, and for each
$y_i$ the completion of $\mathcal{O}_{Y^\nu, y_i}$ is normal.
\end{enumerate}

statement_tex:
\label{theorem-resolve}
\begin{reference}
\cite[Theorem on page 151]{Lipman}
\end{reference}
Let $Y$ be a two dimensional integral Noetherian scheme. The following are
equivalent
\begin{enumerate}
\item there exists an alteration $X \to Y$ with $X$ regular,
