statement:
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally \'etale,
\item $H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

statement_tex:
\label{lemma-NL-formally-etale}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is formally \'etale,
\item $H^{-1}(\NL_{X/Y}) = H^0(\NL_{X/Y}) = 0$.
\end{enumerate}

\label{lemma-periodic-determinant-easy-case}
Let $R$ be a local ring with residue field $\kappa$.
Let $M$ be a finite length $R$-module.
\begin{enumerate}
\item if $\varphi : M \to M$ is an isomorphism then
$\det_\kappa(M, \varphi, 0) = \det_\kappa(\varphi)$.
\item if $\psi : M \to M$ is an isomorphism then
$\det_\kappa(M, 0, \psi) = \det_\kappa(\psi)^{-1}$.
\end{enumerate}

\label{lemma-base-change-quasi-compact}
The base change of a quasi-compact morphism of algebraic stacks
by any morphism of algebraic stacks is quasi-compact.

\label{lemma-descending-property-thickening}
The property of being a thickening is fpqc local.
Similarly for first order thickenings.

\label{lemma-cohomology-istar-Z}
For all $q \geq 1$, $H_\etale^q(X, \bigoplus_{x \in X_0} {i_x}_*
\underline{\mathbf{Z}}) = 0$.

\label{lemma-surjective-finite-morphism-ample}
Let $R$ be a Noetherian ring. Let $f : Y \to X$ be a morphism of
algebraic spaces proper over $R$. Let $\mathcal{L}$ be an
invertible $\mathcal{O}_X$-module. Assume $f$ is finite and surjective.
The following are equivalent
\begin{enumerate}
\item $X$ is a scheme and $\mathcal{L}$ is ample, and
\item $Y$ is a scheme and $f^*\mathcal{L}$ is ample.
\end{enumerate}

\label{lemma-hom-from-Af}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $f$ be a global
section of $\mathcal{O}$. Let $K \in D(\mathcal{O})$.
The following are equivalent
\begin{enumerate}
\item $R\SheafHom_\mathcal{O}(\mathcal{O}_f, K) = 0$,
\item $R\SheafHom_\mathcal{O}(L, K) = 0$ for all $L$ in $D(\mathcal{O}_f)$,
\item $T(K, f) = 0$.
\end{enumerate}

\label{lemma-zariski-etale-smooth}
Any \'etale covering is a smooth covering, and a fortiori,
any Zariski covering is a smooth covering.

\label{lemma-cone}
The cone on a morphism of strictly perfect complexes is
strictly perfect.

\label{lemma-gorenstein}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item If $X$ has a dualizing complex $\omega_X^\bullet$, then
\begin{enumerate}
\item $X$ is Gorenstein $\Leftrightarrow$ $\omega_X^\bullet$ is an invertible
object of $D(\mathcal{O}_X)$,
\item $\mathcal{O}_{X, x}$ is Gorenstein $\Leftrightarrow$
$\omega_{X, x}^\bullet$ is an invertible object of $D(\mathcal{O}_{X, x})$,
\item $U = \{x \in X \mid \mathcal{O}_{X, x}\text{ is Gorenstein}\}$
is an open Gorenstein subscheme.
\end{enumerate}
\item If $X$ is Gorenstein, then $X$ has a dualizing complex if and
only if $\mathcal{O}_X[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-smooth-formally-smooth}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth, and
\item the morphism $f$ is locally of finite presentation and
formally smooth.
\end{enumerate}

\label{lemma-when-jshriek-compact}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $U$ be an object of
$\mathcal{C}$. The $\mathcal{O}$-module $j_!\mathcal{O}_U$ is a
compact object of $D(\mathcal{O})$ if there exists an integer $d$ such that
\begin{enumerate}
\item $H^p(U, \mathcal{F}) = 0$ for all $p > d$, and
\item the functors $\mathcal{F} \mapsto H^p(U, \mathcal{F})$
commute with direct sums.
\end{enumerate}

\label{lemma-decompose-quasi-finite-morphism}
Let $f : Y \to X$ be a quasi-finite and finitely presented
morphism of affine schemes.
\begin{enumerate}
\item There exists a surjective morphism of affine schemes $X' \to X$ and a
closed subscheme $Z' \subset Y' = X' \times_X Y$ such that
\begin{enumerate}
\item $Z' \subset Y'$ is a thickening, and
\item $Z' \to X'$ is a finite \'etale morphism.
\end{enumerate}
\item There exists a finite partition $X = \coprod X_i$ by
locally closed, constructible, affine strata, and surjective finite locally
free morphisms $X'_i \to X_i$ such that the reduction of
$Y'_i = X'_i \times_X Y \to X'_i$ is isomorphic to
$\coprod_{j = 1}^{n_i} (X'_i)_{red} \to (X'_i)_{red}$ for some $n_i$.
\end{enumerate}

\label{lemma-pro-h-V}
Let $X \to Y$ be a morphism of affine schemes. The following are equivalent
\begin{enumerate}
\item $\{X \to Y\}$ is a standard V covering
(Topologies, Definition \ref{topologies-definition-standard-V-covering}),
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is a ph covering for each $i$, and
\item $X = \lim X_i$ is a directed limit of affine schemes over $Y$
such that $\{X_i \to Y\}$ is an h covering for each $i$.
\end{enumerate}

statement:
\begin{reference}
\cite[Theorem 3.1]{CD}
\end{reference}
Let $A$ be a Noetherian local ring with completion $A^\wedge$.
Let $I \subset A$ be an ideal such that
$$
\dim V(IA^\wedge + \mathfrak p) \geq 1
$$
for every minimal prime $\mathfrak p \subset A^\wedge$ of dimension $\dim(A)$.
Then $\text{cd}(A, I) < \dim(A)$.

statement_tex:
\label{proposition-Hartshorne-Lichtenbaum-vanishing}
\begin{reference}
\cite[Theorem 3.1]{CD}
\end{reference}
Let $A$ be a Noetherian local ring with completion $A^\wedge$.
Let $I \subset A$ be an ideal such that
$$
\dim V(IA^\wedge + \mathfrak p) \geq 1
$$
for every minimal prime $\mathfrak p \subset A^\wedge$ of dimension $\dim(A)$.
Then $\text{cd}(A, I) < \dim(A)$.

\label{lemma-smash-nilpotence}
\begin{reference}
\cite{nilpotence}
\end{reference}
Let $k$ be a field. Let $X$ be a geometrically irreducible
smooth projective scheme over $k$. Let $x, x' \in X$ be $k$-rational points.
For $n$ large enough the class of the zero cycle
$$
([x] - [x']) \times \ldots \times ([x] - [x']) \in
\CH_0(X^n)
$$
is torsion.

statement:
Let $X$ be a scheme. The rule which associates to a closed subscheme
of $X$ its underlying closed subset defines a bijection
$$
\left\{
\begin{matrix}
\text{closed subschemes }Z \subset X \\
\text{such that }Z \to X\text{ is flat}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{closed subsets }Z \subset X \\
\text{closed under generalizations}
\end{matrix}
\right\}
$$
If $Z \subset X$ is such a closed subscheme, every morphism of schemes
$g : Y \to X$ with $g(Y) \subset Z$ set theoretically factors (scheme
theoretically) through $Z$.

statement_tex:
\label{lemma-characterize-flat-closed-immersions}
Let $X$ be a scheme. The rule which associates to a closed subscheme
of $X$ its underlying closed subset defines a bijection
$$
\left\{
\begin{matrix}
\text{closed subschemes }Z \subset X \\
\text{such that }Z \to X\text{ is flat}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{closed subsets }Z \subset X \\
\text{closed under generalizations}
\end{matrix}
\right\}
$$
If $Z \subset X$ is such a closed subscheme, every morphism of schemes
$g : Y \to X$ with $g(Y) \subset Z$ set theoretically factors (scheme
theoretically) through $Z$.

\label{theorem-check-flatness-at-associated-points}
Let $f : X \to S$ be locally of finite type.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module of finite type.
Let $x \in X$ with image $s \in S$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is flat at $x$ over $S$, and
\item for every $x' \in \text{Ass}_{X_s}(\mathcal{F}_s)$ which
specializes to $x$ we have that $\mathcal{F}$ is flat at $x'$ over $S$.
\end{enumerate}

\label{lemma-hom-into-depth}
Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$, $\mathcal{G}$
be coherent $\mathcal{O}_X$-modules and $x \in X$.
\begin{enumerate}
\item If $\mathcal{G}_x$ has depth $\geq 1$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})_x$
has depth $\geq 1$.
\item If $\mathcal{G}_x$ has depth $\geq 2$, then
$\Hom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})_x$ has depth $\geq 2$.
\end{enumerate}

\label{lemma-stable-reduction}
Let $R$ be a discrete valuation ring with fraction field $K$.
Let $C$ be a smooth projective curve over $K$ with
$K = H^0(C, \mathcal{O}_C)$ having genus $g \geq 2$.
The following are equivalent
\begin{enumerate}
\item $C$ has semistable reduction
(Semistable Reduction, Definition \ref{models-definition-semistable}), or
\item there is a stable family of curves over $R$ with generic fibre $C$.
\end{enumerate}

\label{theorem-splitting}
Let $A$ be a finite central simple $k$-algebra.
Let $k'/k$ be a finite field extension.
The following are equivalent
\begin{enumerate}
\item $k'$ splits $A$, and
\item there exists a finite central simple algebra $B$ similar to $A$
such that $k' \subset B$ and $[B : k] = [k' : k]^2$.
\end{enumerate}

\label{lemma-flattening-module-map}
Let $A$ be a ring. Let $u : M \to N$ be a surjective map of $A$-modules.
If $M$ is projective as an $A$-module, then there exists an ideal
$I \subset A$ such that for any ring map $\varphi : A \to B$
the following are equivalent
\begin{enumerate}
\item $u \otimes 1 : M \otimes_A B \to N \otimes_A B$ is an
isomorphism, and
\item $\varphi(I) = 0$.
\end{enumerate}

\label{lemma-shriek-proper-and-open-base-change}
Let $b : Y_1 \to Y$ be a morphism of schemes. Consider a commutative diagram
of schemes
$$
\vcenter{
\xymatrix{
X' \ar[r]_{g'} \ar[d]_{f'} & X \ar[d]^f \\
Y' \ar[r]^g & Y
}
}
\quad\text{and let}\quad
\vcenter{
\xymatrix{
X'_1 \ar[r]_{g'_1} \ar[d]_{f'_1} & X_1 \ar[d]^{f_1} \\
Y'_1 \ar[r]^{g_1} & Y_1
}
}
$$
be the base change by $b$. Assume $f$ and $f'$ proper and
$g$ and $g'$ separated and locally quasi-finite.
For a ring $\Lambda$ and $K$ in $D(X'_\etale, \Lambda)$
there is commutative diagram
$$
\xymatrix{
b^{-1}g_!Rf'_*K \ar[d] \ar[r] &
g_{1, !}(b')^{-1}Rf'_*K \ar[r] &
g_{1, !}Rf'_{1, *}(a')^{-1}K \ar[d] \\
b^{-1}Rf_*g'_!K \ar[r] &
Rf_{1, *}a^{-1}g'_!K \ar[r] &
Rf_{1, *}g'_{1, !}(a')^{-1}K
}
$$
in $D(Y_{1, \etale}, \Lambda)$ where $a : X_1 \to X$, $a' : X'_1 \to X'$,
$b' : Y'_1 \to Y'$ are the projections, the vertical maps are the arrows
of Lemma \ref{lemma-shriek-proper-and-open}
and the horizontal arrows are the base change map
(from \'Etale Cohomology, Section
\ref{etale-cohomology-section-base-change-preliminaries})
and the base change map of Lemma \ref{lemma-base-change-f-shriek-separated}.

statement:
Let $S$ be a scheme. Let $\{X_i \to X\}_{i \in I}$ be an fppf
covering of algebraic spaces over $S$ (Topologies on Spaces,
Definition \ref{spaces-topologies-definition-fppf-covering}).
There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{descent data }(V_i, \varphi_{ij})\\
\text{relative to }\{X_i \to X\}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{sheaves }F\text{ on }(\Sch/S)_{fppf}\text{ endowed}\\
\text{with a map }F \to X\text{ such that each}\\
X_i \times_X F\text{ is an algebraic space}
\end{matrix}
\right\}.
$$
Moreover,
\begin{enumerate}
\item the algebraic space $X_i \times_X F$ on the right hand side
corresponds to $V_i$ on the left hand side, and
\item the sheaf $F$ is an algebraic space\footnote{We will see
later that this is always the case if $I$ is not too large, see
Bootstrap, Lemma \ref{bootstrap-lemma-descend-algebraic-space}.}
if and only if the
corresponding descent datum $(X_i, \varphi_{ij})$ is effective.
\end{enumerate}

statement_tex:
\label{lemma-descent-data-sheaves}
Let $S$ be a scheme. Let $\{X_i \to X\}_{i \in I}$ be an fppf
covering of algebraic spaces over $S$ (Topologies on Spaces,
Definition \ref{spaces-topologies-definition-fppf-covering}).
There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{descent data }(V_i, \varphi_{ij})\\
\text{relative to }\{X_i \to X\}
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{sheaves }F\text{ on }(\Sch/S)_{fppf}\text{ endowed}\\
\text{with a map }F \to X\text{ such that each}\\
X_i \times_X F\text{ is an algebraic space}
\end{matrix}
\right\}.
$$
Moreover,
\begin{enumerate}
\item the algebraic space $X_i \times_X F$ on the right hand side
corresponds to $V_i$ on the left hand side, and
\item the sheaf $F$ is an algebraic space\footnote{We will see
later that this is always the case if $I$ is not too large, see
Bootstrap, Lemma \ref{bootstrap-lemma-descend-algebraic-space}.}
if and only if the
corresponding descent datum $(X_i, \varphi_{ij})$ is effective.
\end{enumerate}

statement:
The functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
(\ref{item-integrable}), and (\ref{item-topologically-quasi-nilpotent})}
\end{matrix}
$$
of Lemma \ref{lemma-crystals-on-affine}
is an equivalence of categories.

statement_tex:
\label{proposition-crystals-on-affine}
The functor
$$
\begin{matrix}
\text{crystals in quasi-coherent} \\
\mathcal{O}_{X/S}\text{-modules on }\text{Cris}(X/S)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{pairs }(M, \nabla)\text{ satisfying} \\
\text{(\ref{item-complete}), (\ref{item-connection}),
