\label{lemma-flat-lci}
\begin{slogan}
Syntomic equals flat plus lci (for algebraic spaces).
\end{slogan}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ is flat and a local complete intersection morphism, and
\item $f$ is syntomic.
\end{enumerate}

\label{lemma-unramified-formally-unramified}
\begin{slogan}
Unramified morphisms are the same as formally unramified morphism that
are locally of finite type.
\end{slogan}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is unramified (resp.\ G-unramified), and
\item the morphism $f$ is locally of finite type (resp.\ locally of finite
presentation) and formally unramified.
\end{enumerate}

\label{lemma-resolution-property-finite-number}
Let $X$ be a scheme. Suppose given
\begin{enumerate}
\item a finite affine open covering $X = U_1 \cup \ldots \cup U_m$
\item finite type quasi-coherent ideals $\mathcal{I}_j$
with $V(\mathcal{I}_j) = X \setminus U_j$
\end{enumerate}
Then $X$ has the resolution property if and only if $\mathcal{I}_j$
is the quotient of a finite locally free $\mathcal{O}_X$-module
for $j = 1, \ldots, m$.

\label{lemma-identify-pseudo-coherent-noetherian}
Let $S$ be a scheme. Let $X$ be a Noetherian algebraic space over $S$.
Let $E$ be an object of $D_\QCoh(\mathcal{O}_X)$. For
$m \in \mathbf{Z}$ the following are equivalent
\begin{enumerate}
\item $H^i(E)$ is coherent for $i \geq m$ and zero for $i \gg 0$, and
\item $E$ is $m$-pseudo-coherent.
\end{enumerate}
In particular, $E$ is pseudo-coherent if and only if $E$ is an object
of $D^-_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-descending-property-affine}
The property $\mathcal{P}(f) =$``$f$ is affine''
is fpqc local on the base.

\label{lemma-characterize-surjective}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
which is representable by algebraic spaces. The following are equivalent:
\begin{enumerate}
\item $|f| : |\mathcal{X}| \to |\mathcal{Y}|$ is surjective, and
\item $f$ is surjective
(in the sense of Section \ref{section-properties-morphisms}).
\end{enumerate}

\label{lemma-generic-point-in-constructible}
Let $X$ be a scheme and let $E \subset X$ be a locally constructible subset.
Let $\xi \in X$ be a generic point of an irreducible component of $X$.
\begin{enumerate}
\item If $\xi \in E$, then an open neighbourhood of
$\xi$ is contained in $E$.
\item If $\xi \not \in E$, then an open neighbourhood
of $\xi$ is disjoint from $E$.
\end{enumerate}

statement:
\begin{reference}
\cite[II, Corollary 1.3.2]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is affine.
\item There exists an affine open covering $S = \bigcup W_j$
such that each $f^{-1}(W_j)$ is affine.
\item There exists a quasi-coherent sheaf of $\mathcal{O}_S$-algebras
$\mathcal{A}$ and an isomorphism
$X \cong \underline{\Spec}_S(\mathcal{A})$
of schemes over $S$. See
Constructions, Section \ref{constructions-section-spec} for notation.
\end{enumerate}
Moreover, in this case $X = \underline{\Spec}_S(f_*\mathcal{O}_X)$.

statement_tex:
\label{lemma-characterize-affine}
\begin{reference}
\cite[II, Corollary 1.3.2]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is affine.
\item There exists an affine open covering $S = \bigcup W_j$
such that each $f^{-1}(W_j)$ is affine.
\item There exists a quasi-coherent sheaf of $\mathcal{O}_S$-algebras
$\mathcal{A}$ and an isomorphism
$X \cong \underline{\Spec}_S(\mathcal{A})$
of schemes over $S$. See
Constructions, Section \ref{constructions-section-spec} for notation.
\end{enumerate}
Moreover, in this case $X = \underline{\Spec}_S(f_*\mathcal{O}_X)$.

\label{lemma-closed-is-complete}
Let $I \subset R$ be an ideal of a ring. Let $M$ be an $I$-adically complete
$R$-module and let $N \subset M$ be a submodule. The following are equivalent
\begin{enumerate}
\item $N$ is closed in $M$,
\item $N = \bigcap_{n \geq 1} (N + I^n M)$,
\item $M/N$ is $I$-adically complete
\end{enumerate}
If $I$ is finitely generated, these conditions imply that $N$
is $I$-adically complete.

\label{lemma-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is open''
is fppf local on the source.

\label{lemma-skyscraper-modules-exact}
Let $(\Sh(\mathcal{C}), \mathcal{O})$ be a ringed topos.
Let $p$ be a point of the topos $\Sh(\mathcal{C})$.
\begin{enumerate}
\item The functor
$p_* : \textit{Mod}(\mathcal{O}_p) \to \textit{Mod}(\mathcal{O})$,
$M \mapsto p_*M$ is exact.
\item The canonical surjection $p^{-1}p_*M \to M$ is $\mathcal{O}_p$-linear.
\item The functorial direct sum decomposition
$p^{-1}p_*M = M \oplus I(M)$ of Lemma \ref{lemma-skyscraper-exact}
is {\bf not} $\mathcal{O}_p$-linear in general.
\end{enumerate}

\label{lemma-smooth-properties}
Let $\varphi : \mathcal{F} \to \mathcal{G}$ and $\psi : \mathcal{G}
\to \mathcal{H}$ be morphisms of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$.
\begin{enumerate}
\item If $\varphi$ and $\psi$ are smooth, then $\psi \circ \varphi$ is smooth.
\item If $\varphi$ is essentially surjective and $\psi \circ \varphi$ is
smooth, then $\psi$ is smooth.
\item If $\mathcal{G}' \to \mathcal{G}$ is a morphism of categories
cofibered in groupoids and $\varphi$ is smooth, then
$\mathcal{F} \times_\mathcal{G} \mathcal{G}' \to \mathcal{G}'$ is smooth.
\end{enumerate}

\label{lemma-resolution-property-goes-down-finite-flat}
Let $f : X \to Y$ be a surjective finite locally free morphism of schemes.
If $X$ has the resolution property, so does $Y$.

\label{lemma-zariski-etale-smooth}
Any \'etale covering is a smooth covering, and a fortiori,
any Zariski covering is a smooth covering.

\label{lemma-adic-homomorphism}
Let $A$ and $B$ be pre-adic topological rings. Let
$\varphi : A \to B$ be a continuous ring homomorphism.
\begin{enumerate}
\item If $\varphi$ is adic, then $\varphi$ is taut.
\item If $B$ is complete, $A$ has a finitely generated
ideal of definition, and $\varphi$ is taut, then $\varphi$ is adic.
\end{enumerate}
In particular the conditions ``$\varphi$ is adic'' and ``$\varphi$ is taut''
are equivalent on the category $\textit{WAdm}^{adic*}$.

