statement:
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $U \subset X$ be the open subspace
with $|U| = |X| \setminus T$. The completion functor
(\ref{equation-completion-functor})
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces}\\
f : X' \to X\text{ which are locally}\\
\text{of finite type and such that}\\
f^{-1}U \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{morphisms }g : W \to X_{/T}\\
\text{of formal algebraic spaces}\\
\text{with }W\text{ locally Noetherian}\\
\text{and }g\text{ rig-\'etale}
\end{matrix}
\right\}
$$
sending $f : X' \to X$ to $f_{/T} : X'_{/T'} \to X_{/T}$ is an equivalence.

statement_tex:
\label{theorem-dilatations-general}
Let $S$ be a scheme. Let $X$ be a locally Noetherian algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $U \subset X$ be the open subspace
with $|U| = |X| \setminus T$. The completion functor
(\ref{equation-completion-functor})
$$
\left\{
\begin{matrix}
\text{morphisms of algebraic spaces}\\
f : X' \to X\text{ which are locally}\\
\text{of finite type and such that}\\
f^{-1}U \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{morphisms }g : W \to X_{/T}\\
\text{of formal algebraic spaces}\\
\text{with }W\text{ locally Noetherian}\\
\text{and }g\text{ rig-\'etale}
\end{matrix}
\right\}
$$
sending $f : X' \to X$ to $f_{/T} : X'_{/T'} \to X_{/T}$ is an equivalence.

\label{lemma-residual-gerbe-regular}
A reduced, locally Noetherian algebraic stack $\mathcal{Z}$ such that
$|\mathcal{Z}|$ is a singleton is regular.

\label{lemma-criterion-proper}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
Assume $f$ is of finite type and quasi-separated.
Then the following are equivalent
\begin{enumerate}
\item $f$ is proper, and
\item $f$ satisfies both the uniqueness and existence parts
of the valuative criterion.
\end{enumerate}

\label{lemma-there-is-a-scheme-integral-over}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$.
\begin{enumerate}
\item There exists a surjective integral morphism $Y \to X$ where $Y$
is a scheme,
\item given a surjective \'etale morphism $U \to X$ we may choose
$Y \to X$ such that for every $y \in Y$ there is an open neighbourhood
$V \subset Y$ such that $V \to X$ factors through $U$.
\end{enumerate}

\label{lemma-tau-nonzero}
Let $k$ be a field and let $A$ be a finite $k$-algebra. Assume $A$
is local with residue field $k'$. The following are equivalent
\begin{enumerate}
\item $\text{Trace}_{A/k}$ is nonzero,
\item $\tau_{A/k} \in \omega_{A/k}$ is nonzero, and
\item $k'/k$ is separable and $\text{length}_A(A)$ is prime
to the characteristic of $k$.
\end{enumerate}

\label{lemma-length-closed-immersion}
Let $S$ be a scheme. Let $i : Y \to X$ be a closed immersion of
algebraic spaces over $S$. Let $\mathcal{G}$ be a quasi-coherent
$\mathcal{O}_Y$-module. Let $y \in |Y|$ with image $x \in |X|$.
Let $d \in \{0, 1, 2, \ldots, \infty\}$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{G}$ has length $d$ at $y$, and
\item $i_*\mathcal{G}$ has length $d$ at $x$.
\end{enumerate}

statement:
There is a decomposition into open and closed substacks
$$
\Curvesstack^{prestable} = \coprod\nolimits_{g \geq 0}
\Curvesstack^{prestable}_g
$$
where each $\Curvesstack^{prestable}_g$ is characterized as follows:
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}_g$,
\item $X \to S$ is a prestable family of curves and
$R^1f_*\mathcal{O}_X$ is a locally free $\mathcal{O}_S$-module of rank $g$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}_g$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and the genus of $X$ is $g$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-prestable-one-piece-per-genus}
There is a decomposition into open and closed substacks
$$
\Curvesstack^{prestable} = \coprod\nolimits_{g \geq 0}
\Curvesstack^{prestable}_g
$$
where each $\Curvesstack^{prestable}_g$ is characterized as follows:
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}_g$,
\item $X \to S$ is a prestable family of curves and
$R^1f_*\mathcal{O}_X$ is a locally free $\mathcal{O}_S$-module of rank $g$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}_g$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
$k = H^0(X, \mathcal{O}_X)$, and the genus of $X$ is $g$.
\end{enumerate}
\end{enumerate}

\label{theorem-bondal-van-den-bergh}
\begin{reference}
In the projective case this is \cite[Theorem A.1]{BvdB}
\end{reference}
Let $X$ be a proper scheme over a field $k$.
Let $F : D_{perf}(\mathcal{O}_X)^{opp} \to \text{Vect}_k$
be a $k$-linear cohomological functor such that
$$
\sum\nolimits_{n \in \mathbf{Z}} \dim_k F(E[n]) < \infty
$$
for all $E \in D_{perf}(\mathcal{O}_X)$. Then $F$ is isomorphic to a functor
of the form $E \mapsto \Hom_X(E, K)$ for some
$K \in D^b_{\textit{Coh}}(\mathcal{O}_X)$.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

statement:
Let $k$ be a field. Let $n \geq 0$. Let
$K \in D_\QCoh(\mathcal{O}_{\mathbf{P}^n_k})$.
The following are equivalent
\begin{enumerate}
\item $K$ is in $D^b_{\textit{Coh}}(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k H^i(\mathbf{P}^n_k, E \otimes^\mathbf{L} K) < \infty$
for each perfect object $E$ of
$D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k \Ext^i_{\mathbf{P}^n_k}(E, K) < \infty$
for each perfect object $E$ of $D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(\mathbf{P}^n_k,
K \otimes^\mathbf{L} \mathcal{O}_{\mathbf{P}^n_k}(d)) < \infty$
for $d = 0, 1, \ldots, n$.
\end{enumerate}

statement_tex:
\label{lemma-coherent-on-projective-space}
Let $k$ be a field. Let $n \geq 0$. Let
$K \in D_\QCoh(\mathcal{O}_{\mathbf{P}^n_k})$.
The following are equivalent
\begin{enumerate}
\item $K$ is in $D^b_{\textit{Coh}}(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k H^i(\mathbf{P}^n_k, E \otimes^\mathbf{L} K) < \infty$
for each perfect object $E$ of
$D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}}
\dim_k \Ext^i_{\mathbf{P}^n_k}(E, K) < \infty$
for each perfect object $E$ of $D(\mathcal{O}_{\mathbf{P}^n_k})$,
\item $\sum_{i \in \mathbf{Z}} \dim_k H^i(\mathbf{P}^n_k,
K \otimes^\mathbf{L} \mathcal{O}_{\mathbf{P}^n_k}(d)) < \infty$
for $d = 0, 1, \ldots, n$.
\end{enumerate}

\label{lemma-base-change-universally-closed}
The base change of a universally closed morphism of algebraic stacks
by any morphism of algebraic stacks is universally closed.

\label{lemma-family-of-curves-not-scheme}
There exists a field $k$ and a family of curves
$X \to \mathbf{A}^1_k$ such that $X$ is not a scheme.

statement:
Let $S$ be a scheme.
Let $Y \to X$ be a morphism of $(\textit{Spaces}/S)_\etale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in
$\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}|_{X_\etale}$ is injective in $\textit{Ab}(X_\etale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}^\bullet|_{X_\etale}$ is a K-injective complex in
$\textit{Ab}(X_\etale)$,
\end{enumerate}
\end{enumerate}
The corresponding statements for modules do not hold.

statement_tex:
\label{lemma-compare-injectives}
Let $S$ be a scheme.
Let $Y \to X$ be a morphism of $(\textit{Spaces}/S)_\etale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in
$\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}|_{X_\etale}$ is injective in $\textit{Ab}(X_\etale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\textit{Spaces}/X)_\etale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(Y_\etale)$,
\item $\mathcal{I}^\bullet|_{X_\etale}$ is a K-injective complex in
$\textit{Ab}(X_\etale)$,
\end{enumerate}
\end{enumerate}
The corresponding statements for modules do not hold.

\label{lemma-finite-disjoint-quasi-compact}
A finite disjoint union of quasi-compact algebraic spaces is
a quasi-compact algebraic space.

\label{lemma-identifies-residue-fields}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of decent
algebraic spaces over $S$. Let $x \in |X|$ be a point
with image $y = f(x) \in |Y|$.
The following are equivalent
\begin{enumerate}
\item $f$ induces an isomorphism $\kappa(y) \to \kappa(x)$, and
\item the induced morphism $\Spec(\kappa(x)) \to Y$ is a monomorphism.
\end{enumerate}

\label{lemma-schemes-morphisms-RS}
Example \ref{example-schemes-morphisms}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{X \to Y}$ is a deformation category
for any morphism of schemes $X \to Y$ over $k$.

\label{lemma-compose-after-separated}
Let $S$ be a scheme.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of algebraic spaces over $S$.
\begin{enumerate}
\item If $g \circ f$ is separated then so is $f$.
\item If $g \circ f$ is locally separated then so is $f$.
\item If $g \circ f$ is quasi-separated then so is $f$.
\end{enumerate}

\label{proposition-when-gerbe-over}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is a gerbe over $\mathcal{Y}$, and
\item $f : \mathcal{X} \to \mathcal{Y}$ and
$\Delta : \mathcal{X} \to \mathcal{X} \times_\mathcal{Y} \mathcal{X}$
are surjective, flat, and locally of finite presentation.
\end{enumerate}

\label{lemma-pic-functor-qs-lfp}
The morphism $\Picardfunctor_{X/B} \to B$ is quasi-separated and
locally of finite presentation.

\label{lemma-completion-polynomial-ring-not-flat}
There exists a ring such that the completion $R[[x]]$ of $R[x]$
at $(x)$ is not flat over $R$ and a fortiori not flat over $R[x]$.

statement:
There exist an open substack $\Curvesstack^{prestable} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{prestable}$,
\item $X \to S$ is a prestable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
and $k = H^0(X, \mathcal{O}_X)$.
\end{enumerate}
\end{enumerate}

statement_tex:
