through $\Curvesstack^{prestable}$,
\item $X \to S$ is a prestable family of curves,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$
factors through $\Curvesstack^{prestable}$,
\item the singularities of $X$ are at-worst-nodal, $\dim(X) = 1$,
and $k = H^0(X, \mathcal{O}_X)$.
\end{enumerate}
\end{enumerate}

\label{lemma-bounded-below}
If $U = \Spec(A)$ is an affine scheme, then the bounded
below version
\begin{equation}
\label{equation-compare-bounded-adequate}
D^+(\textit{Adeq}(\mathcal{O}))
\longrightarrow
D^+_{\textit{Adeq}}(\mathcal{O})
\end{equation}
of the functor above is an equivalence.

\label{lemma-well-nigh-affine}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is well-nigh affine, and
\item there exists a groupoid scheme $(U, R, s, t, c)$ with $U$ and
$R$ affine and $s, t : R \to U$ finite locally free such that
$\mathcal{X} = [U/R]$.
\end{enumerate}
If true then $\mathcal{X}$ is quasi-compact, quasi-DM, and separated.

\label{lemma-smooth}
In Example \ref{example-rings} let $P$ be a smooth $k$-algebra. Then
$T\Deformationcategory_P = (0)$.

\label{lemma-universally-injective}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item the map $X(K) \to Y(K)$ is injective for every field $K$ over $S$
\item for every morphism $Y' \to Y$ of algebraic spaces over $S$
the induced map $|Y' \times_Y X| \to |Y'|$ is injective, and
\item the diagonal morphism $X \to X \times_Y X$ is surjective.
\end{enumerate}

\label{lemma-descent-ascent}
Let $\varphi : A \to B$ be a homomorphism of Noetherian rings. Assume
\begin{enumerate}
\item $A \to B$ is syntomic and induces a surjective map on spectra, or
\item $A \to B$ is a faithfully flat local complete intersection, or
\item $A \to B$ is faithfully flat of finite type with Gorenstein fibres.
\end{enumerate}
Then $K \in D(A)$ is a dualizing complex for $A$ if and only if
$K \otimes_A^\mathbf{L} B$ is a dualizing complex for $B$.

\label{lemma-perfect}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site.
Let $E$ be an object of $D(\mathcal{O})$.
The following are equivalent
\begin{enumerate}
\item $E$ is perfect, and
\item $E$ is pseudo-coherent and locally has finite tor dimension.
\end{enumerate}

\label{proposition-presheaves-injectives}
For abelian presheaves on a category there is a functorial injective
embedding.

\label{lemma-pseudo-coherent-hocolim}
Let $S$ be a scheme.
Let $X$ be a quasi-compact and quasi-separated algebraic space over $S$.
Let $K \in D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $K$ is pseudo-coherent, and
\item $K = \text{hocolim} K_n$ where
$K_n$ is perfect and $\tau_{\geq -n}K_n \to \tau_{\geq -n}K$
is an isomorphism for all $n$.
\end{enumerate}

\label{lemma-properties-covering-imply-diagonal}
Let $\mathcal{X}$ be an algebraic stack.
Let $W$ be an algebraic space, and let $f : W \to \mathcal{X}$
be a surjective, flat, locally finitely presented morphism.
\begin{enumerate}
\item If $f$ is unramified (i.e., \'etale, i.e., $\mathcal{X}$
is Deligne-Mumford), then $\mathcal{X}$ is DM.
\item If $f$ is locally quasi-finite, then $\mathcal{X}$ is quasi-DM.
\end{enumerate}

\label{lemma-descending-fppf-property-immersion}
The property $\mathcal{P}(f) =$``$f$ is an immersion''
is fppf local on the base.

\label{lemma-essential-extensions-in-injective}
Let $R$ be a ring. Let $I$ be an injective $R$-module. Let $E \subset I$
be a submodule. The following are equivalent
\begin{enumerate}
\item $E$ is injective, and
\item for all $E \subset E' \subset I$ with $E \subset E'$ essential
we have $E = E'$.
\end{enumerate}
In particular, an $R$-module is injective if and only if every essential
extension is trivial.

\label{lemma-local-source-target-global-implies-local}
Let $\mathcal{P}$ be a property of morphisms of schemes
which is \'etale local on the source-and-target.
Consider the property $\mathcal{Q}$ of morphisms
of germs associated to $\mathcal{P}$ in
Descent, Lemma \ref{descent-lemma-local-source-target-global-implies-local}.
Then
\begin{enumerate}
\item $\mathcal{Q}$ is \'etale local on the source-and-target.
\item given a morphism of algebraic spaces $f : X \to Y$ and $x \in |X|$
the following are equivalent
\begin{enumerate}
\item $f$ has $\mathcal{Q}$ at $x$, and
\item there is an open neighbourhood $X' \subset X$ of $x$
such that $X' \to Y$ has $\mathcal{P}$.
\end{enumerate}
\item given a morphism of algebraic spaces $f : X \to Y$
the following are equivalent:
\begin{enumerate}
\item $f$ has $\mathcal{P}$,
\item for every $x \in |X|$ the morphism $f$ has $\mathcal{Q}$ at $x$.
\end{enumerate}
\end{enumerate}

\label{lemma-unique-point}
Let $S$ be a scheme.
Let $Z$ be an algebraic space over $S$. The following are equivalent
\begin{enumerate}
\item $Z$ is reduced and $|Z|$ is a singleton,
\item there exists a surjective flat morphism $\Spec(k) \to Z$
where $k$ is a field, and
\item there exists a locally of finite type, surjective, flat morphism
$\Spec(k) \to Z$ where $k$ is a field.
\end{enumerate}

\label{lemma-ideal-projective-not-locally-free}
There exists a ring $R$ and an ideal $I$ such that $I$ is projective as
an $R$-module but not locally free as an $R$-module.

\label{lemma-composition-quasi-compact}
The composition of a pair of quasi-compact morphisms of algebraic spaces
is quasi-compact.

\label{lemma-base-change-universally-closed}
The base change of a universally closed morphism of algebraic spaces
by any morphism of algebraic spaces is universally closed.

\label{lemma-non-quasi-separated-group-scheme}
There exists a flat group scheme of finite type over the infinite
dimensional affine space which is not quasi-separated.

\label{lemma-flat-precompose-pus}
In diagram (\ref{equation-base-change}) the map
$a \circ Rg_* \leftarrow Rg'_* \circ a'$ is an isomorphism.

\label{lemma-forget-injectives}
The forgetful functor $\textit{Ab}(\mathcal{C})\to \textit{PAb}(\mathcal{C})$
transforms injectives into injectives.

statement:
\begin{reference}
\cite[IV Theorem 11.3.1]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $f : X \to S$ be a morphism which is locally of finite presentation.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module which is
locally of finite presentation. Then
$$
U = \{x \in X \mid \mathcal{F}\text{ is flat over }S\text{ at }x\}
$$
is open in $X$.

statement_tex:
\label{theorem-openness-flatness}
\begin{reference}
\cite[IV Theorem 11.3.1]{EGA}
\end{reference}
Let $S$ be a scheme.
Let $f : X \to S$ be a morphism which is locally of finite presentation.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module which is
locally of finite presentation. Then
$$
U = \{x \in X \mid \mathcal{F}\text{ is flat over }S\text{ at }x\}
$$
is open in $X$.

\label{lemma-diagonal-unramified-morphism}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is unramified, then the diagonal morphism
$\Delta : X \to X \times_S X$ is an open immersion.
\item If $f$ is locally of finite type
and $\Delta$ is an open immersion, then $f$ is unramified.
\item If $f$ is locally of finite presentation and $\Delta$ is an open
immersion, then $f$ is G-unramified.
\end{enumerate}

\label{lemma-depth-drops-by-one}
Let $A$ be a Noetherian ring, let $I \subset A$ be an ideal, and
let $M$ a finite $A$-module with $IM \not = M$.
\begin{enumerate}
\item If $x \in I$ is a nonzerodivisor on $M$, then
$\text{depth}_I(M/xM) = \text{depth}_I(M) - 1$.
\item Any $M$-regular sequence $x_1, \ldots, x_r$ in $I$ can be extended to an
$M$-regular sequence in $I$ of length $\text{depth}_I(M)$.
\end{enumerate}

\label{lemma-composition-separated}
All of the separation axioms listed in Definition \ref{definition-separated}
are stable under composition of morphisms.

statement:
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite locally free,
\item $f$ is finite, flat, and locally of finite presentation.
\end{enumerate}
If $Y$ is locally Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] $f$ is finite and flat.
\end{enumerate}

statement_tex:
\label{lemma-finite-flat}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite locally free,
\item $f$ is finite, flat, and locally of finite presentation.
\end{enumerate}
If $Y$ is locally Noetherian these are also equivalent to
\begin{enumerate}
\item[(3)] $f$ is finite and flat.
\end{enumerate}

\label{lemma-noether-different-base-change}
Let $A \to B$ be a finite type ring map. Let $A \to A'$ be a flat ring map.
Set $B' = B \otimes_A A'$.
\begin{enumerate}
\item The annihilator $J'$ of $\Ker(B' \otimes_{A'} B' \to B')$ is
$J \otimes_A A'$ where $J$ is the annihilator of $\Ker(B \otimes_A B \to B)$.
\item The Noether different $\mathfrak{D}'$ of $B'$ over $A'$ is
$\mathfrak{D}B'$, where $\mathfrak{D}$ is
the Noether different of $B$ over $A$.
\end{enumerate}

