through $\Curvesstack^{h0, 1}$,
\item $H^0(X, \mathcal{O}_X) = k$ and $\dim(X) = 1$.
\end{enumerate}
\end{enumerate}

\label{theorem-DM}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is DM,
\item $\mathcal{X}$ is Deligne-Mumford, and
\item there exists a scheme $W$ and a surjective \'etale
morphism $W \to \mathcal{X}$.
\end{enumerate}

\label{lemma-etale-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is \'etale''
is \'etale local on the source.

