\begin{reference}
Slight improvement of \cite{AT}
\end{reference}
Let $K$ be an algebraically closed field. Let $\mathbf{X}$ be a smooth proper
scheme over $K$. There are at most countably many isomorphism classes
of smooth proper schemes $\mathbf{Y}$ over $K$ which are derived
equivalent to $\mathbf{X}$.

\label{lemma-composition-lci}
The composition of local complete intersection morphisms is
a local complete intersection.

statement:
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$ which has (S1). Let $\xi$ be a versal formal object
of $\mathcal{F}$ lying over $R$. There exists a morphism $\xi' \to \xi$
lying over $R' \subset R$ with the following minimality properties
\begin{enumerate}
\item for every $f : R \to A$ with $A \in \Ob(\mathcal{C}_\Lambda)$
the pushforwards
$$
\vcenter{
\xymatrix{
\xi' \ar[d] \ar[r] & x' \ar[d] \\
\xi \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
R' \ar[d] \ar[r] & f(R') \ar[d] \\
R \ar[r] & A
}
}
$$
produce a minimal object $x' \to x$ of $\mathcal{S}_x$, and
\item for any morphism of formal objects $\xi'' \to \xi'$
the corresponding morphism $R'' \to R'$ is surjective.
\end{enumerate}

statement_tex:
\label{lemma-smallest-where-descends-versal}
Let $\mathcal{F}$ be a category cofibred in groupoids over
$\mathcal{C}_\Lambda$ which has (S1). Let $\xi$ be a versal formal object
of $\mathcal{F}$ lying over $R$. There exists a morphism $\xi' \to \xi$
lying over $R' \subset R$ with the following minimality properties
\begin{enumerate}
\item for every $f : R \to A$ with $A \in \Ob(\mathcal{C}_\Lambda)$
the pushforwards
$$
\vcenter{
\xymatrix{
\xi' \ar[d] \ar[r] & x' \ar[d] \\
\xi \ar[r] & x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
R' \ar[d] \ar[r] & f(R') \ar[d] \\
R \ar[r] & A
}
}
$$
produce a minimal object $x' \to x$ of $\mathcal{S}_x$, and
\item for any morphism of formal objects $\xi'' \to \xi'$
the corresponding morphism $R'' \to R'$ is surjective.
\end{enumerate}

\label{lemma-characterize-finite}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is finite,
\item $f$ is proper with finite fibres,
\item $f$ is proper and locally quasi-finite,
\item $f$ is universally closed, separated, locally of finite type
and has finite fibres.
\end{enumerate}

\label{lemma-unramified-omega-zero}
Let $f : X \to S$ be a morphism of schemes. Then
\begin{enumerate}
\item $f$ is unramified if and only if $f$ is locally of finite type
and $\Omega_{X/S} = 0$, and
\item $f$ is G-unramified if and only if $f$ is locally of finite presentation
and $\Omega_{X/S} = 0$.
\end{enumerate}

statement:
