statement:
Let $A$ be a Noetherian ring. The following are equivalent
\begin{enumerate}
\item $A$ has finite injective dimension as a module over itself,
\item $A$ is Gorenstein and finite dimensional.
\end{enumerate}
In this case $A[0]$ is a dualizing complex.

statement_tex:
\label{lemma-characterize-gorenstein}
Let $A$ be a Noetherian ring. The following are equivalent
\begin{enumerate}
\item $A$ has finite injective dimension as a module over itself,
\item $A$ is Gorenstein and finite dimensional.
\end{enumerate}
In this case $A[0]$ is a dualizing complex.

\label{lemma-zariski-h}
An fppf covering is a h covering. Hence syntomic, smooth, \'etale,
and Zariski coverings are h coverings as well.

\label{lemma-composition-is-addition}
The bijection (\ref{equation-isomorphism}) is an isomorphism
of groups.

\label{lemma-base-change-stabilizer-preserving}
Let
$$
\xymatrix{
\mathcal{X}' \ar[r] \ar[d]_{f'} & \mathcal{X} \ar[d]^f \\
\mathcal{Y}' \ar[r] & \mathcal{Y}
}
$$
be a cartesian diagram of algebraic stacks.
\begin{enumerate}
\item Let $x' \in |\mathcal{X}'|$ with image $x \in |\mathcal{X}|$.
If $f$ induces an isomorphism between automorphism groups at
$x$ and $f(x)$ (Remark \ref{remark-identify-automorphism-groups}), then
$f'$ induces an isomorphism between automorphism groups at $x'$ and $f(x')$.
\item If $\mathcal{I}_\mathcal{X} \to
\mathcal{X} \times_\mathcal{Y} \mathcal{I}_\mathcal{Y}$ is an isomorphism,
then $\mathcal{I}_{\mathcal{X}'} \to
\mathcal{X}' \times_{\mathcal{Y}'} \mathcal{I}_{\mathcal{Y}'}$
is an isomorphism.
\end{enumerate}

statement:
\begin{reference}
\cite[Corollary 2.7]{DM}
\end{reference}
Let $R$ be a discrete valuation ring with fraction field $K$. Let $C$ be a
smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$
and genus $g \geq 2$. Then
\begin{enumerate}
\item there exists an extension of discrete valuation rings $R \subset R'$
inducing a finite separable extension of fraction fields $K'/K$ and
a stable family of curves $Y \to \Spec(R')$ of genus $g$ with
$Y_{K'} \cong C_{K'}$ over $K'$, and
\item there exists a finite separable extension $L/K$ and a stable
family of curves $Y \to \Spec(A)$ of genus $g$ where $A \subset L$
is the integral closure of $R$ in $L$ such that
$Y_L \cong C_L$ over $L$.
\end{enumerate}

statement_tex:
\label{theorem-stable-reduction}
\begin{reference}
\cite[Corollary 2.7]{DM}
\end{reference}
Let $R$ be a discrete valuation ring with fraction field $K$. Let $C$ be a
smooth projective curve over $K$ with $H^0(C, \mathcal{O}_C) = K$
and genus $g \geq 2$. Then
\begin{enumerate}
\item there exists an extension of discrete valuation rings $R \subset R'$
inducing a finite separable extension of fraction fields $K'/K$ and
a stable family of curves $Y \to \Spec(R')$ of genus $g$ with
$Y_{K'} \cong C_{K'}$ over $K'$, and
\item there exists a finite separable extension $L/K$ and a stable
family of curves $Y \to \Spec(A)$ of genus $g$ where $A \subset L$
is the integral closure of $R$ in $L$ such that
$Y_L \cong C_L$ over $L$.
\end{enumerate}

\label{lemma-composition-universally-submersive}
The composition of a pair of (universally) submersive morphisms of
algebraic stacks is (universally) submersive.

\label{theorem-enough-injectives}
The category of abelian sheaves on a site is an abelian category
which has enough injectives.

\label{lemma-support-sheaf-rings-closed}
The support of a sheaf of rings on the small \'etale site of an
algebraic space is closed.

\label{lemma-CM}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Cohen-Macaulay, and
\item $f$ is flat and its fibres are Cohen-Macaulay schemes.
\end{enumerate}

\label{lemma-exists-smooth}
There exists an $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$
such that the equivalent conditions of Lemma \ref{lemma-smooth}
hold and moreover $H_1(L_{k/\Lambda}) = \mathfrak m_R/\mathfrak m_R^2$
and $\Omega_{R/\Lambda} \otimes_R k = \Omega_{k/\Lambda}$.

\label{lemma-characterize-finite-type}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of formal algebraic
spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is of finite type,
\item $f$ is representable by algebraic spaces and is of finite type in
the sense of
Bootstrap, Definition \ref{bootstrap-definition-property-transformation}.
\end{enumerate}

\label{lemma-geometrically-reduced}
Let $k$ be a field. Let $X$ be an algebraic space over $k$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically reduced,
\item for some surjective \'etale morphism $U \to X$ where $U$
is a scheme, $U$ is geometrically reduced,
\item for any \'etale morphism $U \to X$
where $U$ is a scheme, $U$ is geometrically reduced.
\end{enumerate}

