\label{theorem-popescu}
Any regular homomorphism of Noetherian rings is a filtered colimit
of smooth ring maps.

\label{lemma-comparison-ph-etale}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item For $\mathcal{F} \in \Sh(X_\etale)$ we have
$\epsilon_{X, *}a_X^{-1}\mathcal{F} = \pi_X^{-1}\mathcal{F}$
and $a_{X, *}a_X^{-1}\mathcal{F} = \mathcal{F}$.
\item For $\mathcal{F} \in \textit{Ab}(X_\etale)$ torsion we have
$R^i\epsilon_{X, *}(a_X^{-1}\mathcal{F}) = 0$ for $i > 0$.
\end{enumerate}

\label{lemma-normal-scheme-with-alg-closed-function-field}
Let $X$ be an integral normal scheme with separably closed
function field.
\begin{enumerate}
\item A separated \'etale morphism $U \to X$ is a
disjoint union of open immersions.
\item All local rings of $X$ are strictly henselian.
\end{enumerate}

\label{lemma-descending-property-finite-presentation}
The property $\mathcal{P}(f) =$``$f$ is of finite presentation''
is fpqc local on the base.

\label{lemma-taut-weakly-admissible}
Let $\varphi : A \to B$ be a continuous map of weakly admissible topological
rings. The following are equivalent
\begin{enumerate}
\item $\varphi$ is taut,
\item for every weak ideal of definition $I \subset A$ the closure of
$\varphi(I)B$ is a weak ideal of definition of $B$ and these form a
fundamental system of weak ideals of definition of $B$.
\end{enumerate}

\label{proposition-torsion-complete}
\begin{reference}
This is a special case of \cite[Theorem 1.1]{Porta-Liran-Yekutieli}.
\end{reference}
Let $A$ be a ring and let $I \subset A$ be a finitely generated ideal.
The functors $R\Gamma_Z$ and ${\ }^\wedge$
define quasi-inverse equivalences of categories
$$
D_{I^\infty\text{-torsion}}(A) \leftrightarrow D_{comp}(A, I)
$$

\label{proposition-flat-finite-type-finite-presentation-domain}
Let $R$ be a domain. Let $R \to S$ be a ring map of finite type.
Let $M$ be a finite $S$-module.
\begin{enumerate}
\item If $S$ is flat over $R$, then $S$ is a finitely presented $R$-algebra.
\item If $M$ is flat as an $R$-module, then $M$ is finitely presented
as an $S$-module.
\end{enumerate}

\label{lemma-support-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is in the support of $M$, and
\item $x$ is in the support of $\mathcal{F}$.
\end{enumerate}

\label{lemma-geomred-in-CM}
We have $\Curvesstack^{geomred} \subset \Curvesstack^{CM}$
as open substacks of $\Curvesstack$.

\label{lemma-lift-map-plus}
The result of Lemma \ref{lemma-lift-map} holds even for
