statement:
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under composition of morphisms.

statement_tex:
\label{lemma-composition-separated}
All of the separation axioms listed in
Definition \ref{definition-separated-morphism}
are stable under composition of morphisms.

\label{lemma-gorenstein}
Let $A$ be a Noetherian ring.
\begin{enumerate}
\item If $A$ has a dualizing complex $\omega_A^\bullet$, then
\begin{enumerate}
\item $A$ is Gorenstein $\Leftrightarrow$ $\omega_A^\bullet$ is an invertible
object of $D(A)$,
\item $A_\mathfrak p$ is Gorenstein $\Leftrightarrow$
$(\omega_A^\bullet)_\mathfrak p$ is an invertible object of
$D(A_\mathfrak p)$,
\item $\{\mathfrak p \in \Spec(A) \mid A_\mathfrak p\text{ is Gorenstein}\}$
is an open subset.
\end{enumerate}
\item If $A$ is Gorenstein, then $A$ has a dualizing complex if and
only if $A[0]$ is a dualizing complex.
\end{enumerate}

\label{lemma-monomorphism-injective-points}
\begin{slogan}
Monomorphisms of stacks are injective on points.
\end{slogan}
A monomorphism of algebraic stacks induces an injective map of
sets of points.

\label{lemma-refine-by-h}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms such that $f_i$ is locally of finite presentation for all $i$.
The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is an h covering,
\item there is an h covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is an h covering.
\end{enumerate}

\label{lemma-representations-RS}
Example \ref{example-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-functor-quasi-coherent-from-affine-diagonal}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$. Assume $X$ is
quasi-compact with affine diagonal.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear exact functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which commute with arbitrary direct sums, and
\item the full subcategory of $\QCoh(\mathcal{O}_{X \times_R Y})$ consisting
of $\mathcal{K}$ such that
\begin{enumerate}
\item $\mathcal{K}$ is flat over $X$,
\item for $\mathcal{F} \in \QCoh(\mathcal{O}_X)$ we have
$R^q\text{pr}_{2, *}(\text{pr}_1^*\mathcal{F}
\otimes_{\mathcal{O}_{X \times_R Y}} \mathcal{K}) = 0$ for $q > 0$.
\end{enumerate}
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

\label{lemma-pic-diagonal-affine-fp}
The diagonal of $\Picardstack_{X/B}$ over $B$ is affine
and of finite presentation.

statement:
There exist an open substack $\Curvesstack^{geomred} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item the fibres of the morphism $X \to S$ are geometrically reduced
(More on Morphisms of Spaces, Definition
\ref{spaces-more-morphisms-definition-geometrically-reduced-fibre}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item $X$ is geometrically reduced over $k$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-geometrically-reduced-curves}
There exist an open substack $\Curvesstack^{geomred} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item the fibres of the morphism $X \to S$ are geometrically reduced
(More on Morphisms of Spaces, Definition
\ref{spaces-more-morphisms-definition-geometrically-reduced-fibre}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{geomred}$,
\item $X$ is geometrically reduced over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-deform-property-fp-over-ft}
Consider a commutative diagram
$$
\xymatrix{
(X \subset X') \ar[rr]_{(f, f')} \ar[rd] & & (Y \subset Y') \ar[ld] \\
& (S \subset S')
}
$$
of thickenings. Assume $Y' \to S'$ locally of finite type,
$X' \to S'$ flat and locally of finite presentation,
$X = S \times_{S'} X'$, and $Y = S \times_{S'} Y'$. Then
\begin{enumerate}
\item $f$ is flat if and only if $f'$ is flat,
\label{item-flat-fp-over-ft}
\item $f$ is an isomorphism if and only if $f'$ is an isomorphism,
\label{item-isomorphism-fp-over-ft}
\item $f$ is an open immersion if and only if $f'$ is an open immersion,
\label{item-open-immersion-fp-over-ft}
\item $f$ is quasi-compact if and only if $f'$ is quasi-compact,
\label{item-quasi-compact-fp-over-ft}
\item $f$ is universally closed if and only if $f'$ is universally closed,
\label{item-universally-closed-fp-over-ft}
\item $f$ is (quasi-)separated if and only if $f'$ is (quasi-)separated,
\label{item-separated-fp-over-ft}
\item $f$ is a monomorphism if and only if $f'$ is a monomorphism,
\label{item-monomorphism-fp-over-ft}
\item $f$ is surjective if and only if $f'$ is surjective,
\label{item-surjective-fp-over-ft}
\item $f$ is universally injective if and only if $f'$ is universally injective,
\label{item-universally-injective-fp-over-ft}
\item $f$ is affine if and only if $f'$ is affine,
\label{item-affine-fp-over-ft}
\item $f$ is locally quasi-finite if and only if $f'$ is locally quasi-finite,
\label{item-quasi-finite-fp-over-ft}
\item
\label{item-relative-dimension-d-fp-over-ft}
$f$ is locally of finite type of relative dimension $d$ if and only if
$f'$ is locally of finite type of relative dimension $d$,
\item $f$ is universally open if and only if $f'$ is universally open,
\label{item-universally-open-fp-over-ft}
\item $f$ is syntomic if and only if $f'$ is syntomic,
\label{item-syntomic-fp-over-ft}
\item $f$ is smooth if and only if $f'$ is smooth,
\label{item-smooth-fp-over-ft}
\item $f$ is unramified if and only if $f'$ is unramified,
\label{item-unramified-fp-over-ft}
\item $f$ is \'etale if and only if $f'$ is \'etale,
\label{item-etale-fp-over-ft}
\item $f$ is proper if and only if $f'$ is proper,
\label{item-proper-fp-over-ft}
\item $f$ is finite if and only if $f'$ is finite,
\label{item-finite-fp-over-ft}
\item
\label{item-finite-locally-free-fp-over-ft}
$f$ is finite locally free (of rank $d$) if and only if $f'$
is finite locally free (of rank $d$), and
\item add more here.
\end{enumerate}

\label{lemma-char-p}
Let $p$ be a prime number.
\begin{enumerate}
\item If $A$ is an $\mathbf{F}_p$-algebra, then $\colim_F A = A^{awn}$.
\item If $S$ is a scheme over $\mathbf{F}_p$, then the
h sheafification of $\mathcal{O}$ sends a quasi-compact
and quasi-separated $X$ to $\colim_F \Gamma(X, \mathcal{O}_X)$.
\end{enumerate}

\label{lemma-descending-property-lci}
The property $\mathcal{P}(f) =$``$f$ is a local complete intersection
morphism'' is fpqc local on the base.

statement:
There exist an open substack
$\Curvesstack^{+} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{+}$,
\item the singular locus of $X \to S$ endowed
with any/some closed subspace structure is finite over $S$.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{+}$,
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-isolated-sings-curves}
There exist an open substack
$\Curvesstack^{+} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{+}$,
\item the singular locus of $X \to S$ endowed
with any/some closed subspace structure is finite over $S$.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{+}$,
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
\end{enumerate}

\label{lemma-groupoid-on-field-explain-points}
Let $S$ be a scheme. Let $(U, R, s, t, c)$ be a groupoid scheme
over $S$. Assume $U = \Spec(k)$ with $k$ a field.
For any point $r \in R$ there exist
\begin{enumerate}
\item a field extension $k'/k$ with $k'$ algebraically closed,
\item a point $r' \in R'$ where $(U', R', s', t', c')$ is the
restriction of $(U, R, s, t, c)$ via $\Spec(k') \to \Spec(k)$
\end{enumerate}
such that
\begin{enumerate}
\item the point $r'$ maps to $r$ under the morphism $R' \to R$, and
\item the maps $s', t' : R' \to \Spec(k')$ induce isomorphisms
$k' \to \kappa(r')$.
\end{enumerate}

\label{lemma-rig-etale-finite-type}
A rig-\'etale morphism of locally Noetherian formal algebraic spaces
is locally of finite type.

\label{lemma-pushout-along-closed-immersion-and-integral}
In More on Morphisms, Situation
\ref{more-morphisms-situation-pushout-along-closed-immersion-and-integral},
for example if $Z \to Y$ and $Z \to X$ are closed immersions of schemes,
there is an equivalence of categories
$$
\textit{F\'Et}_{Y \amalg_Z X}
\longrightarrow
\textit{F\'Et}_Y
\times_{\textit{F\'Et}_Z}
\textit{F\'Et}_X
$$

\label{lemma-curves-qs-lfp}
The morphism $\Curvesstack \to \Spec(\mathbf{Z})$ is quasi-separated and
locally of finite presentation.

\label{lemma-descending-property-finite-locally-free}
The property $\mathcal{P}(f) =$``$f$ is finite locally free''
is fpqc local on the base.

\label{lemma-flat-rig-surjective}
Let $A$ be a Noetherian ring complete with respect to an ideal $I$.
Let $B$ be an $I$-adically complete $A$-algebra. Assume that
\begin{enumerate}
\item the $I$-torsion in $A$ is $0$,
\item $A/I^n \to B/I^nB$ is flat and of finite type for all $n$.
\end{enumerate}
Then $\text{Spf}(B) \to \text{Spf}(A)$ is rig-surjective if and only
if $A/I \to B/IB$ is faithfully flat.

\label{lemma-closed-immersion-proper}
A closed immersion of algebraic spaces is a proper morphism of
algebraic spaces.

\label{lemma-pic-gerbe-over-pic-functor}
The morphism $\Picardstack_{X/B} \to \Picardfunctor_{X/B}$
turns the Picard stack into a gerbe over the Picard functor.

\label{lemma-vanishing-affine-char-p-p}
Let $p$ be a prime. Let $S$ be a scheme of characteristic $p$.
\begin{enumerate}
\item If $S$ is affine, then
$H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$ for all
$q \geq 2$.
\item If $S$ is a quasi-compact and quasi-separated scheme of
dimension $d$, then $H_\etale^q(S, \underline{\mathbf{Z}/p\mathbf{Z}}) = 0$
for all $q \geq 2 + d$.
\end{enumerate}

statement:
Let $f : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$.
\begin{enumerate}
\item The functor $f$ transforms fibre products into fibre products.
\item If $f$ is faithful, then $f$ transforms equalizers into equalizers.
\end{enumerate}

statement_tex:
\label{lemma-fibre-products-morphism}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$.
\begin{enumerate}
\item The functor $f$ transforms fibre products into fibre products.
\item If $f$ is faithful, then $f$ transforms equalizers into equalizers.
\end{enumerate}

\label{lemma-surjection-from-quasi-compact}
\begin{slogan}
The image of a quasi-compact algebraic space under a surjective morphism
is quasi-compact.
\end{slogan}
Let $S$ be a scheme.
\begin{enumerate}
\item If $X \to Y$ is a surjective morphism of algebraic spaces over $S$,
and $X$ is quasi-compact then $Y$ is quasi-compact.
\item If
$$
\xymatrix{
X \ar[rr]_f \ar[rd]_p & &
Y \ar[dl]^q \\
& Z
}
$$
is a commutative diagram of morphisms of algebraic spaces over $S$
and $f$ is surjective and $p$ is quasi-compact, then $q$ is quasi-compact.
\end{enumerate}

\label{lemma-composition-finite-type}
The composition of two morphisms which are locally of finite type is
locally of finite type. The same is true for morphisms of finite type.

\label{lemma-where-smooth}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic
spaces over $S$. There is a largest open subspace $U \subset X$
such that $f|_U : U \to Y$ is smooth. Moreover, formation of
this open commutes with base change by
\begin{enumerate}
\item morphisms which are flat and
locally of finite presentation,
\item flat morphisms provided $f$ is locally of finite presentation.
\end{enumerate}

\label{lemma-cech-exact-presheaves}
The functor given by Equation (\ref{equation-cech-functor})
is an exact functor (see Homology, Lemma \ref{homology-lemma-exact-functor}).

statement:
\begin{reference}
Email by Ofer Gabber of September 11, 2014.
\end{reference}
Let $S$ be a scheme. Let $X = \Spec(A)$ be an affine scheme over $S$.
Let $T \subset X$ be a closed subscheme.
\begin{enumerate}
\item If the formal completion $X_{/T}$ is countably indexed
and there exist countably many $f_1, f_2, f_3, \ldots \in A$ such that
$T = V(f_1, f_2, f_3, \ldots)$, then $X_{/T}$ is adic*.
\item The conclusion of (1) is wrong if we omit the assumption that
$T$ can be cut out by countably many functions in $X$.
\end{enumerate}

statement_tex:
\label{lemma-completion-countably-indexed}
\begin{reference}
Email by Ofer Gabber of September 11, 2014.
\end{reference}
Let $S$ be a scheme. Let $X = \Spec(A)$ be an affine scheme over $S$.
Let $T \subset X$ be a closed subscheme.
\begin{enumerate}
\item If the formal completion $X_{/T}$ is countably indexed
and there exist countably many $f_1, f_2, f_3, \ldots \in A$ such that
$T = V(f_1, f_2, f_3, \ldots)$, then $X_{/T}$ is adic*.
\item The conclusion of (1) is wrong if we omit the assumption that
$T$ can be cut out by countably many functions in $X$.
\end{enumerate}

\label{proposition-Garel}
\begin{reference}
\cite{Garel}
\end{reference}
Let $f : Y \to X$ be a finite syntomic morphism of schemes.
The maps $\Theta^p_{Y/X}$ of Lemma \ref{lemma-Garel} define a map of complexes
$$
\Theta_{Y/X} :
f_*\Omega^\bullet_{Y/\mathbf{Z}}
\longrightarrow
\Omega^\bullet_{X/\mathbf{Z}}
$$
with the following properties
\begin{enumerate}
\item in degree $0$ we get
$\text{Trace}_f : f_*\mathcal{O}_Y \to \mathcal{O}_X$, see
Discriminants, Section \ref{discriminant-section-discriminant},
\item we have
$\Theta_{Y/X}(\omega \wedge \eta) = \omega \wedge \Theta_{Y/X}(\eta)$
for $\omega$ in $\Omega^\bullet_{X/\mathbf{Z}}$ and $\eta$
in $f_*\Omega^\bullet_{Y/\mathbf{Z}}$,
\item if $f$ is a morphism over a base scheme $S$, then
$\Theta_{Y/X}$ induces a map of complexes
$f_*\Omega^\bullet_{Y/S} \to \Omega^\bullet_{X/S}$.
\end{enumerate}

\label{lemma-functor-modules}
Let $R$ be a ring. Let $A$ and $B$ be $R$-algebras. There is an
equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \text{Mod}_A \to \text{Mod}_B$ which
are right exact and commute with arbitrary direct sums, and
\item the category $\text{Mod}_{A \otimes_R B}$.
\end{enumerate}
given by sending $K$ to the functor $F$ in (\ref{equation-FM-modules}).

\label{lemma-base-change-quasi-finite}
A base change of a quasi-finite morphism is quasi-finite.
The same holds for locally quasi-finite.

\label{lemma-non-flat-group-scheme}
There exists a group scheme $G$ over a base $S$ whose identity
component is flat over $S$ but which is not flat over $S$.

\label{lemma-base-change-universally-injective}
The base change of a universally injective morphism of algebraic stacks
by any morphism of algebraic stacks is universally injective.

\label{lemma-lim-not-quasi-compact}
There exists an inverse system of quasi-compact topological spaces
over $\mathbf{N}$ whose limit is not quasi-compact.

statement:
Let the algebraic stack $\mathcal{X}$ be well-nigh affine.
\begin{enumerate}
\item If $\mathcal{X}$ is an algebraic space, then it is affine.
\item If $\mathcal{X}' \to \mathcal{X}$ is an affine morphism
of algebraic stacks, then $\mathcal{X}'$ is well-nigh affine.
\end{enumerate}

statement_tex:
\label{lemma-affine-over-well-nigh-affine}
Let the algebraic stack $\mathcal{X}$ be well-nigh affine.
\begin{enumerate}
\item If $\mathcal{X}$ is an algebraic space, then it is affine.
\item If $\mathcal{X}' \to \mathcal{X}$ is an affine morphism
of algebraic stacks, then $\mathcal{X}'$ is well-nigh affine.
\end{enumerate}

\label{lemma-zariski-etale-smooth-syntomic-fppf-ph}
Any fppf covering is a ph covering, and a fortiori,
any syntomic, smooth, \'etale or Zariski covering is a ph covering.

\label{lemma-finite-etale-stack}
The functor
$$
p : \textit{F\'Et} \longrightarrow (\Sch/S)_{fppf}
$$
defines a stack over $(\Sch/S)_{fppf}$.

statement:
Let $f : X \to S$ be a morphism of schemes. The construction
$$
\begin{matrix}
\text{category of cartesian } \\
\text{schemes over } (X/S)_\bullet
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/S
\end{matrix}
$$
of Lemma \ref{lemma-cartesian-over}
is an equivalence of categories.

statement_tex:
\label{lemma-cartesian-equivalent-descent-datum}
Let $f : X \to S$ be a morphism of schemes. The construction
$$
\begin{matrix}
\text{category of cartesian } \\
\text{schemes over } (X/S)_\bullet
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/S
\end{matrix}
$$
of Lemma \ref{lemma-cartesian-over}
is an equivalence of categories.

\label{lemma-noncomplete-completion}
There exists a local ring $R$ and a maximal ideal $\mathfrak m$ such that
the completion $R^\wedge$ of $R$ with respect to $\mathfrak m$ has the
following properties
\begin{enumerate}
\item $R^\wedge$ is local, but its maximal ideal is not equal to
$\mathfrak m R^\wedge$,
\item $R^\wedge$ is not a complete local ring, and
\item $R^\wedge$ is not $\mathfrak m$-adically complete as an $R$-module.
\end{enumerate}

\label{lemma-keel-mori-diagonal}
Let $\mathcal{X}$ be an algebraic stack. Assume
$\mathcal{I}_\mathcal{X} \to \mathcal{X}$ is finite.
Let $f : \mathcal{X} \to M$ be the moduli space constructed in
Theorem \ref{theorem-keel-mori}.
\begin{enumerate}
\item If $\mathcal{X}$ is quasi-separated, then $M$ is quasi-separated.
\item If $\mathcal{X}$ is separated, then $M$ is separated.
\item Add more here, for example relative versions of the above.
\end{enumerate}

\label{lemma-nonsplit-locally-split}
There exists a ring $R$ and a nonsplit sequence of modules
which becomes split Zariski locally.

\label{lemma-DM-curves}
There exist an open substack $\Curvesstack^{DM} \subset \Curvesstack$
with the following properties
\begin{enumerate}
\item $\Curvesstack^{DM} \subset \Curvesstack$ is the maximal
open substack which is DM,
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{DM}$,
\item the group algebraic space $\mathit{Aut}_S(X)$ is unramified over $S$,
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{DM}$,
\item $\mathit{Aut}(X)$ is geometrically reduced over $k$ and
has dimension $0$,
\item $\mathit{Aut}(X) \to \Spec(k)$ is unramified.
\end{enumerate}
\end{enumerate}

\label{lemma-etale-formally-etale}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is \'etale, and
\item the morphism $f$ is locally of finite presentation and
formally \'etale.
\end{enumerate}

\label{lemma-descending-property-thickening}
The property of being a thickening is fpqc local.
Similarly for first order thickenings.

statement:
Let $X$ be a scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is Nagata, and
\item $X$ is locally Noetherian and universally Japanese.
\end{enumerate}

statement_tex:
\label{lemma-nagata-universally-Japanese}
Let $X$ be a scheme.
The following are equivalent:
\begin{enumerate}
\item $X$ is Nagata, and
\item $X$ is locally Noetherian and universally Japanese.
\end{enumerate}

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of algebraic spaces
by any morphism of algebraic spaces is universally submersive.

statement:
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is unramified, and
\item $f$ is locally of finite type and its diagonal is \'etale.
\end{enumerate}

statement_tex:
\label{lemma-characterize-unramified}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
The following are equivalent
\begin{enumerate}
\item $f$ is unramified, and
\item $f$ is locally of finite type and its diagonal is \'etale.
\end{enumerate}

\label{lemma-descending-property-locally-finite-type}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type''
is fpqc local on the base.

\label{lemma-number-of-branches-1}
Let $X$ be a scheme. Let $x \in X$.
\begin{enumerate}
\item The number of branches of $X$ at $x$ is $1$ if and only if
$X$ is unibranch at $x$.
\item The number of geometric branches of $X$ at $x$ is $1$ if and only if
$X$ is geometrically unibranch at $x$.
\end{enumerate}

\label{lemma-representable-quasi-separated-diagonal-quasi-compact}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks
representable by algebraic spaces. Then the following are equivalent
\begin{enumerate}
\item $f$ is quasi-separated,
\item $\Delta_f$ is quasi-compact, or
\item $\Delta_f$ is of finite type.
\end{enumerate}

\label{lemma-Noetherian-topology}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item If $X$ is locally Noetherian then $|X|$ is a locally Noetherian
topological space.
\item If $X$ is quasi-compact and locally Noetherian, then $|X|$
is a Noetherian topological space.
\end{enumerate}

\label{lemma-refine-by-V}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family
of morphisms. The following are equivalent
\begin{enumerate}
\item $\{T_i \to T\}_{i \in I}$ is a V covering,
\item there is a V covering which refines $\{T_i \to T\}_{i \in I}$, and
\item $\{\coprod_{i \in I} T_i \to T\}$ is a V covering.
\end{enumerate}

\label{lemma-descending-property-unramified}
The property $\mathcal{P}(f) =$``$f$ is unramified''
is fpqc local on the base.

statement:
\begin{reference}
The case of a finite order thickening is \cite[Proposition 5.1.9]{EGA1}.
\end{reference}
Any thickening of an affine scheme is affine.

statement_tex:
\label{lemma-thickening-affine-scheme}
\begin{slogan}
Affineness is insensitive to thickenings
\end{slogan}
\begin{reference}
The case of a finite order thickening is \cite[Proposition 5.1.9]{EGA1}.
\end{reference}
Any thickening of an affine scheme is affine.

\label{lemma-deform}
Let $(f, f') : (X \subset X') \to (S \subset S')$ be a morphism
of first order thickenings. Assume that $f$ is flat.
Then the following are equivalent
\begin{enumerate}
\item $f'$ is flat and $X = S \times_{S'} X'$, and
\item the canonical map $f^*\mathcal{C}_{S/S'} \to \mathcal{C}_{X/X'}$
is an isomorphism.
\end{enumerate}

\label{lemma-NL-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is smooth, and
\item $f$ is locally of finite presentation,
$H^{-1}(\NL_{X/Y}) = 0$, and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is finite locally free.
\end{enumerate}

\label{lemma-finite-separated-flat-locally-finite-presentation}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$ which
is separated, flat, and locally of finite presentation.
In this case
\begin{enumerate}
\item $(X/Y)_{fin} \to Y$ is separated, representable, and \'etale, and
\item if $Y$ is a scheme, then $(X/Y)_{fin}$ is (representable by) a scheme.
\end{enumerate}

statement:
Let $(R, \mathfrak m, \kappa)$ be a Noetherian local ring.
Let $E$ be an injective hull of $\kappa$.
\begin{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the ascending chain condition,
\item $M$ is a finite $R$-module, and
\item there exist $n, m$ and an exact sequence
$R^{\oplus m} \to R^{\oplus n} \to M \to 0$.
\end{enumerate}
\item For an $R$-module $M$ the following are equivalent:
\begin{enumerate}
\item $M$ satisfies the descending chain condition,
\item $M$ is $\mathfrak m$-power torsion and
$\dim_\kappa(M[\mathfrak m]) < \infty$, and
\item there exist $n, m$ and an exact sequence
$0 \to M \to E^{\oplus n} \to E^{\oplus m}$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-describe-categories}
Let $(R, \mathfrak m, \kappa)$ be a Noetherian local ring.
Let $E$ be an injective hull of $\kappa$.
\begin{enumerate}
\item For an $R$-module $M$ the following are equivalent:
