\item there exist $n, m$ and an exact sequence
$0 \to M \to E^{\oplus n} \to E^{\oplus m}$.
\end{enumerate}
\end{enumerate}

\label{lemma-locally-finite-type-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite type''
is fppf local on the source.

\label{lemma-base-change-universal-homeomorphism}
The base change of a universal homeomorphism of algebraic stacks
by any morphism of algebraic stacks is a universal homeomorphism.

statement:
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under base change.

statement_tex:
\label{lemma-base-change-separated}
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under base change.

\label{lemma-decent-irreducible-closed}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
There are canonical bijections between the following sets:
\begin{enumerate}
\item the set of points of $X$, i.e., $|X|$,
\item the set of irreducible closed subsets of $|X|$,
\item the set of integral closed subspaces of $X$.
\end{enumerate}
The bijection from (1) to (2) sends $x$ to $\overline{\{x\}}$.
The bijection from (3) to (2) sends $Z$ to $|Z|$.

statement:
Let $\mathcal{F}$ be a predeformation category satisfying (S1) and
(S2). Let $\xi$ be a formal object of $\mathcal{F}$ corresponding to
$\underline{\xi} : \underline{R}|_{\mathcal{C}_\Lambda} \to \mathcal{F}$, see
Remark \ref{remark-formal-objects-yoneda}.
Then $\xi$ is versal if and only if the following two conditions hold:
\begin{enumerate}
\item the map
$d\underline{\xi} : T\underline{R}|_{\mathcal{C}_\Lambda} \to T\mathcal{F}$
on tangent spaces is surjective, and
\item given a diagram in $\widehat{\mathcal{F}}$
$$
\vcenter{
\xymatrix{
            &  y \ar[d] \\
\xi \ar[r]  &  x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[r] &   A
}
}
$$
in $\widehat{\mathcal{C}}_\Lambda$ with $B \to A$ a small extension of
Artinian rings, then there exists a ring map $R \to B$ such that
$$
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[ur] \ar[r] &   A
}
$$
commutes.
\end{enumerate}

statement_tex:
\label{lemma-versal-criterion}
Let $\mathcal{F}$ be a predeformation category satisfying (S1) and
(S2). Let $\xi$ be a formal object of $\mathcal{F}$ corresponding to
$\underline{\xi} : \underline{R}|_{\mathcal{C}_\Lambda} \to \mathcal{F}$, see
Remark \ref{remark-formal-objects-yoneda}.
Then $\xi$ is versal if and only if the following two conditions hold:
\begin{enumerate}
\item the map
$d\underline{\xi} : T\underline{R}|_{\mathcal{C}_\Lambda} \to T\mathcal{F}$
on tangent spaces is surjective, and
\item given a diagram in $\widehat{\mathcal{F}}$
$$
\vcenter{
\xymatrix{
            &  y \ar[d] \\
\xi \ar[r]  &  x
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[r] &   A
}
}
$$
in $\widehat{\mathcal{C}}_\Lambda$ with $B \to A$ a small extension of
Artinian rings, then there exists a ring map $R \to B$ such that
$$
\xymatrix{
         &   B  \ar[d]^{f} \\
R \ar[ur] \ar[r] &   A
}
$$
commutes.
\end{enumerate}

\label{lemma-unramified-locally-finite-type}
An unramified morphism is locally of finite type.
A G-unramified morphism is locally of finite presentation.

statement:
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is catenary, and
\item for any $x \in X$ the local ring $\mathcal{O}_{X, x}$ is
catenary.
\end{enumerate}

statement_tex:
\label{lemma-catenary-local-rings-catenary}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is catenary, and
\item for any $x \in X$ the local ring $\mathcal{O}_{X, x}$ is
catenary.
\end{enumerate}

\label{proposition-regular-ideal}
\begin{reference}
Variant of \cite[Corollary 1]{Vasconcelos}. See also
\cite{Iyengar} and \cite{Ferrand-lci}.
\end{reference}
Let $R$ be a Noetherian ring. Let $I \subset R$ be an ideal
which has finite projective dimension and such that $I/I^2$ is
finite locally free over $R/I$. Then $I$ is a regular ideal
(More on Algebra, Definition \ref{more-algebra-definition-regular-ideal}).

statement:
\begin{reference}
