statement:
Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
\begin{enumerate}
\item The morphism $f$ is locally separated.
\item The morphism $f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
above if and only if $f$ is (quasi-)separated in the sense of
Section \ref{section-representable}.
\end{enumerate}
In particular, if $f : X \to Y$ is a morphism of schemes over $S$, then
$f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
if and only if $f$ is (quasi-)separated as a morphism of schemes.

statement_tex:
\label{lemma-match-separated}
Let $S$ be a scheme.
Let $f : X \to Y$ be a representable morphism of algebraic spaces over $S$.
\begin{enumerate}
\item The morphism $f$ is locally separated.
\item The morphism $f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
above if and only if $f$ is (quasi-)separated in the sense of
Section \ref{section-representable}.
\end{enumerate}
In particular, if $f : X \to Y$ is a morphism of schemes over $S$, then
$f$ is (quasi-)separated in the sense of
Definition \ref{definition-separated}
if and only if $f$ is (quasi-)separated as a morphism of schemes.

\label{lemma-NL-smooth}
Let $f : X \to Y$ be a morphism of schemes. The following are equivalent
\begin{enumerate}
\item $f$ is smooth, and
\item $f$ is locally of finite presentation,
$H^{-1}(\NL_{X/Y}) = 0$, and $H^0(\NL_{X/Y}) = \Omega_{X/Y}$
is finite locally free.
\end{enumerate}

\label{lemma-locally-quasi-finite}
Let $S$ be a scheme. Let $f : X \to Y$ be a morphism of algebraic spaces.
Assume $f$ is locally of finite type. The following are equivalent
\begin{enumerate}
\item $f$ is locally quasi-finite,
\item for every morphism $\Spec(k) \to Y$ where $k$ is a field
the space $|X_k|$ is discrete. Here $X_k = \Spec(k) \times_Y X$.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Assume $\dim(X) \leq d$ for some integer $d$.
Let $\mathcal{F}$ be a quasi-coherent sheaf $\mathcal{F}$ on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for any quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ for any closed subspace
$Z \subset X$ whose complement is quasi-compact.
\end{enumerate}

statement_tex:
\label{lemma-vanishing-above-dimension}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$. Assume $\dim(X) \leq d$ for some integer $d$.
Let $\mathcal{F}$ be a quasi-coherent sheaf $\mathcal{F}$ on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for any quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ for any closed subspace
$Z \subset X$ whose complement is quasi-compact.
\end{enumerate}

statement:
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-excellent, and
\item $X$ is a G-scheme and J-2.
\end{enumerate}

statement_tex:
\label{lemma-characterize-quasi-excellent}
Let $X$ be a scheme. The following are equivalent
\begin{enumerate}
\item $X$ is quasi-excellent, and
\item $X$ is a G-scheme and J-2.
\end{enumerate}

\label{lemma-base-change-local-isomorphism}
Let $A \to B$ and $A \to A'$ be ring maps. Let $B' = B \otimes_A A'$
be the base change of $B$.
\begin{enumerate}
\item If $A \to B$ is a local isomorphism, then $A' \to B'$ is a
local isomorphism.
\item If $A \to B$ identifies local rings, then $A' \to B'$
identifies local rings.
\end{enumerate}

\label{lemma-non-separated-group-space}
There exists a group algebraic space of finite type over a field
which is not separated (and not even quasi-separated or locally separated).

\label{lemma-unique-point}
Let $\mathcal{Z}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{Z}$ is reduced and $|\mathcal{Z}|$ is a singleton,
\item there exists a surjective flat morphism $\Spec(k) \to \mathcal{Z}$
where $k$ is a field, and
\item there exists a locally of finite type, surjective, flat morphism
$\Spec(k) \to \mathcal{Z}$ where $k$ is a field.
\end{enumerate}

statement:
\begin{reference}
\cite[Theorem 1.6]{Varbaro}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian complete local ring.
Let $I$ be a proper ideal of $A$.
Set $X = \Spec(A)$ and $Y = V(I)$.
Denote
\begin{enumerate}
\item $d$ the minimal dimension of an irreducible component of $X$, and
\item $c$ the minimal dimension of a closed subset $Z \subset X$
such that $X \setminus Z$ is disconnected.
\end{enumerate}
Then for $Z \subset Y$ closed we have $Y \setminus Z$ is connected if
$\dim(Z) < \min(c, d - 1) - \text{cd}(A, I)$. In particular, the punctured
spectrum of $A/I$ is connected if $\text{cd}(A, I) < \min(c, d - 1)$.

statement_tex:
\label{lemma-punctured-still-connected}
\begin{reference}
\cite[Theorem 1.6]{Varbaro}
\end{reference}
Let $(A, \mathfrak m)$ be a Noetherian complete local ring.
Let $I$ be a proper ideal of $A$.
Set $X = \Spec(A)$ and $Y = V(I)$.
Denote
\begin{enumerate}
\item $d$ the minimal dimension of an irreducible component of $X$, and
\item $c$ the minimal dimension of a closed subset $Z \subset X$
such that $X \setminus Z$ is disconnected.
\end{enumerate}
Then for $Z \subset Y$ closed we have $Y \setminus Z$ is connected if
$\dim(Z) < \min(c, d - 1) - \text{cd}(A, I)$. In particular, the punctured
spectrum of $A/I$ is connected if $\text{cd}(A, I) < \min(c, d - 1)$.

\label{lemma-composition-finite-type}
The composition of finite type morphisms is of finite type.
The same holds for locally of finite type.

\label{proposition-find-w-contractible}
For every ring $A$ there exists a faithfully flat, ind-\'etale ring
map $A \to D$ such that $D$ is w-contractible.

statement:
