\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{CM}$,
\item $X$ is Cohen-Macaulay.
\end{enumerate}
\end{enumerate}

\label{lemma-twisted-inverse-image}
\begin{reference}
This is almost the same as \cite[Example 4.2]{Neeman-Grothendieck}.
\end{reference}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism between quasi-separated and quasi-compact
algebraic spaces over $S$. The functor $Rf_* : D_\QCoh(X) \to D_\QCoh(Y)$
has a right adjoint.

\label{lemma-K-flat-resolution}
Let $R$ be a ring. Let $(B, \text{d})$ be a differential graded $R$-algebra.
There exists a quasi-isomorphism $(A, \text{d}) \to (B, \text{d})$ of
differential graded $R$-algebras with the following properties
\begin{enumerate}
\item $A$ is K-flat as a complex of $R$-modules,
\item $A$ is a free graded $R$-algebra.
\end{enumerate}

\label{lemma-dg-hull-acyclic}
The functors $F, G$ of Lemma \ref{lemma-dg-hull} have
the following properties. Given a graded $\mathcal{A}$-module
$\mathcal{N}$ we have
\begin{enumerate}
\item the counit $\mathcal{N} \to F(G(\mathcal{N}))$ is injective,
\item the map $\overline{\text{d}} : \mathcal{N} \to
\Coker(\mathcal{N} \to F(G(\mathcal{N})))[1]$ is an isomorphism, and
\item $G(\mathcal{N})$ is an acyclic differential graded $\mathcal{A}$-module.
\end{enumerate}

\label{proposition-there-is-a-scheme-finite-over}
Let $S$ be a scheme. Let $X$ be a quasi-compact and quasi-separated
algebraic space over $S$.
\begin{enumerate}
\item There exists a surjective finite morphism $Y \to X$
of finite presentation where $Y$ is a scheme,
\item given a surjective \'etale morphism $U \to X$ we may choose
$Y \to X$ such that for every $y \in Y$ there is an open neighbourhood
$V \subset Y$ such that $V \to X$ factors through $U$.
\end{enumerate}

\label{lemma-base-change-NL}
Consider a cartesian diagram of schemes
$$
\xymatrix{
X' \ar[r]_{g'} \ar[d] & X \ar[d] \\
Y' \ar[r] & Y
}
$$
The canonical map $(g')^*\NL_{X/Y} \to \NL_{X'/Y'}$ induces
an isomorphism on $H^0$ and a surjection on $H^{-1}$.

\label{lemma-noetherian-finite-type-finite-presentation}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{Y}$ is locally Noetherian and $f$ locally of finite type
then $f$ is locally of finite presentation.
\item If $\mathcal{Y}$ is locally Noetherian and $f$ of finite type and
quasi-separated then $f$ is of finite presentation.
\end{enumerate}

\label{lemma-Mor-diagonal-closed}
The diagonal of $\mathit{Mor}_B(Y, X) \to B$ is a closed immersion
of finite presentation.

\label{lemma-smooth-formally-smooth}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is smooth.
\item The morphism $f$ is locally of finite presentation, and
formally smooth.
\end{enumerate}

\label{lemma-kernel-localization}
In Definition \ref{definition-derived-category}
the kernel of the localization functor
$Q : K(\textit{Mod}(\mathcal{A}, \text{d})) \to D(\mathcal{A}, \text{d})$
is the category $\text{Ac}$ of Lemma \ref{lemma-acyclics}.

\label{lemma-gorenstein-morphism}
Let $f : X \to Y$ be a morphism of schemes.
Assume all fibres of $f$ are locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is Gorenstein, and
\item $f$ is flat and its fibres are Gorenstein schemes.
\end{enumerate}

\label{lemma-pure-projective}
Let $A$ be a ring.
\begin{enumerate}
\item A module is pure projective if and only if
it is a direct summand of a direct sum of finitely presented $A$-modules.
\item For any module $M$ there exists a universally exact sequence
$0 \to N \to P \to M \to 0$ with $P$ pure projective.
\end{enumerate}

\label{lemma-characterize-finite}
(For a more general version see
More on Morphisms, Lemma \ref{more-morphisms-lemma-characterize-finite}.)
Let $f : X \to S$ be a morphism of schemes.
Assume $S$ is locally Noetherian.
The following are equivalent
\begin{enumerate}
\item $f$ is finite, and
\item $f$ is proper with finite fibres.
\end{enumerate}

