statement:
Let $S$ be a scheme. Let $T$ be an object of $(\Sch/S)_\proetale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}|_{S_\proetale}$ is injective in $\textit{Ab}(S_\proetale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}^\bullet|_{S_\proetale}$ is a K-injective complex in
$\textit{Ab}(S_\proetale)$,
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-compare-injectives}
Let $S$ be a scheme. Let $T$ be an object of $(\Sch/S)_\proetale$.
\begin{enumerate}
\item If $\mathcal{I}$ is injective in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}$ is injective in $\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}|_{S_\proetale}$ is injective in $\textit{Ab}(S_\proetale)$,
\end{enumerate}
\item If $\mathcal{I}^\bullet$ is a K-injective complex
in $\textit{Ab}((\Sch/S)_\proetale)$, then
\begin{enumerate}
\item $i_f^{-1}\mathcal{I}^\bullet$ is a K-injective complex in
$\textit{Ab}(T_\proetale)$,
\item $\mathcal{I}^\bullet|_{S_\proetale}$ is a K-injective complex in
$\textit{Ab}(S_\proetale)$,
\end{enumerate}
\end{enumerate}

\label{lemma-generic-point-in-schematic-locus}
Let $S$ be a scheme. Let $X$ be a quasi-separated algebraic space over $S$.
Let $x \in |X|$. The following are equivalent
\begin{enumerate}
\item $x$ is a point of codimension $0$ on $X$,
\item the local ring of $X$ at $x$ has dimension $0$, and
\item $x$ is a generic point of an irreducible component of $|X|$.
\end{enumerate}
If true, then there exists an open subspace of $X$
containing $x$ which is a scheme.

\label{lemma-gabriel-popescu-left-adjoint}
The functor $G$ above has a left adjoint
$F : \text{Mod}_R \to \mathcal{A}$.

statement:
Let $S$ be a scheme.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of algebraic spaces over $S$.
\begin{enumerate}
\item If $g \circ f$ is finite and $g$ separated then $f$ is finite.
\item If $g \circ f$ is integral and $g$ separated then $f$ is integral.
\end{enumerate}

statement_tex:
\label{lemma-finite-permanence}
Let $S$ be a scheme.
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of algebraic spaces over $S$.
\begin{enumerate}
\item If $g \circ f$ is finite and $g$ separated then $f$ is finite.
\item If $g \circ f$ is integral and $g$ separated then $f$ is integral.
\end{enumerate}

\label{lemma-fibre-products}
Let $p : \mathcal{X} \to (\Sch/S)_{fppf}$
be a category fibred in groupoids.
\begin{enumerate}
\item The category $\mathcal{X}$ has fibre products.
\item If the $\mathit{Isom}$-presheaves of $\mathcal{X}$
are representable by algebraic spaces, then $\mathcal{X}$ has equalizers.
\item If $\mathcal{X}$ is an algebraic stack (or more generally
a quotient stack), then $\mathcal{X}$ has equalizers.
\end{enumerate}

\label{lemma-base-change-universally-submersive}
The base change of a universally submersive morphism of algebraic stacks
by any morphism of algebraic stacks is universally submersive.

statement:
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is quasi-DM, and
\item there exists a scheme $W$ and a surjective, flat, locally finitely
presented, locally quasi-finite morphism $W \to \mathcal{X}$.
\end{enumerate}

statement_tex:
\label{theorem-quasi-DM}
Let $\mathcal{X}$ be an algebraic stack. The following are equivalent
\begin{enumerate}
\item $\mathcal{X}$ is quasi-DM, and
\item there exists a scheme $W$ and a surjective, flat, locally finitely
presented, locally quasi-finite morphism $W \to \mathcal{X}$.
\end{enumerate}

\label{lemma-tensor-central-simple}
The tensor product of finite central simple algebras over $k$ is finite,
central, and simple.

\label{lemma-descending-property-separated}
The property $\mathcal{P}(f) =$``$f$ is separated''
is fpqc local on the base.

\label{lemma-descending-property-quasi-compact-immersion}
The property $\mathcal{P}(f) =$``$f$ is a quasi-compact immersion''
is fpqc local on the base.

\label{lemma-lift-map}
Let $A$ be a ring. Given a solid diagram
$$
\xymatrix{
0 \ar[r] &
L \ar[d]_\varphi \ar[r] &
\underline{A^{\oplus n}} \ar[r] \ar@{..>}[ld] &
\underline{A^{\oplus m}} \\
& \underline{M}
}
$$
of module-valued functors on $\textit{Alg}_A$
with exact row there exists a dotted arrow making the diagram commute.

\label{lemma-verify-site-proetale}
Let $S$ be a scheme. Let $\Sch_\proetale$ be a big pro-\'etale site
containing $S$. Both $S_\proetale$ and $(\textit{Aff}/S)_\proetale$ are sites.

\label{lemma-site-fpqc}
The collection of fpqc coverings on the category of schemes
satisfies the axioms of site.

statement:
Let $X$ be a scheme and $\mathcal{F}$ a sheaf of sets on $X_\etale$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally constant, and
\item $\mathcal{F} = h_U$ for some finite \'etale morphism $U \to X$.
\end{enumerate}

statement_tex:
\label{lemma-characterize-finite-locally-constant}
Let $X$ be a scheme and $\mathcal{F}$ a sheaf of sets on $X_\etale$.
Then the following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally constant, and
\item $\mathcal{F} = h_U$ for some finite \'etale morphism $U \to X$.
\end{enumerate}

\label{lemma-facts-pext}
Let $A$ be a ring.
\begin{enumerate}
\item $\text{Pext}^i_A(M, N) = 0$ for $i > 0$ whenever $N$ is pure injective,
\item $\text{Pext}^i_A(M, N) = 0$ for $i > 0$ whenever $M$ is pure projective,
in particular if $M$ is an $A$-module of finite presentation,
\item $\text{Pext}^i_A(M, N)$ is also the $i$th cohomology module
of the complex $\Hom_A(P_\bullet, N)$ where $P_\bullet$
is a pure projective resolution of $M$.
\end{enumerate}

\label{lemma-characterize-representable-universally-closed}
Let $S$ be a scheme. Let $f : X \to Y$ be a representable morphism of
algebraic spaces over $S$. The following are equivalent
\begin{enumerate}
\item $f$ is universally closed
(in the sense of Section \ref{section-representable}), and
\item for every morphism of algebraic spaces $Z \to Y$ the morphism of
topological spaces $|Z \times_Y X| \to |Z|$ is closed.
\end{enumerate}

\label{lemma-formal-completion-types}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
Let $T \subset |X|$ be a closed subset. Let $X_{/T}$ be the
formal completion of $X$ along $T$.
\begin{enumerate}
\item If $X \setminus T \to X$ is quasi-compact,
then $X_{/T}$ is locally adic*.
\item If $X$ is locally Noetherian, then $X_{/T}$ is locally
Noetherian.
\end{enumerate}

\label{lemma-representable-by-spaces-limit-preserving}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is limit preserving on objects, and
\item $p$ is locally of finite presentation (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

\label{lemma-torsion-direct-image}
Let $f : X \to Y$ be a quasi-compact and quasi-separated
morphism of schemes.
\begin{enumerate}
\item If $\mathcal{F}$ is a torsion abelian sheaf on $X_\etale$, then
$R^nf_*\mathcal{F}$ is a torsion abelian sheaf on $Y_\etale$ for all $n$.
\item If $K$ in $D^+(X_\etale)$ has torsion cohomology sheaves, then
$Rf_*K$ is an object of $D^+(Y_\etale)$ whose cohomology sheaves are
torsion abelian sheaves.
\end{enumerate}

\label{lemma-point-finite-type}
Let $\mathcal{X}$ be an algebraic stack.
Let $x \in |\mathcal{X}|$. The following are equivalent:
\begin{enumerate}
\item There exists a morphism $\Spec(k) \to \mathcal{X}$
which is locally of finite type and represents $x$.
\item There exists a scheme $U$, a closed point $u \in U$, and a smooth
morphism $\varphi : U \to \mathcal{X}$ such that $\varphi(u) = x$.
\end{enumerate}

\label{lemma-composition-finite-presentation}
The composition of morphisms of finite presentation is of finite presentation.
The same holds for locally of finite presentation.

\label{lemma-flat-base-change-lci}
A flat base change of a local complete intersection morphism is
a local complete intersection morphism.

\label{lemma-composition-lci}
A composition of local complete intersection morphisms is a
local complete intersection morphism.

\label{lemma-hom-into-S2}
Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$, $\mathcal{G}$
be coherent $\mathcal{O}_X$-modules.
\begin{enumerate}
\item If $\mathcal{G}$ has property $(S_1)$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ has property $(S_1)$.
\item If $\mathcal{G}$ has property $(S_2)$, then
$\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{G})$ has property $(S_2)$.
\end{enumerate}

\label{lemma-ci-map-well-defined}
Let $A \to B$ be a local homomorphism of Noetherian complete local rings.
The following are equivalent
\begin{enumerate}
\item for some good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence, and
\item for every good factorization $A \to S \to B$ the kernel of
$S \to B$ is generated by a regular sequence.
\end{enumerate}

\label{lemma-composition-etale}
The composition of two \'etale morphisms of algebraic spaces
is \'etale.

\label{lemma-descending-property-integral}
The property $\mathcal{P}(f) =$``$f$ is integral''
is fpqc local on the base.

\label{lemma-composition-immersion}
Compositions of immersions of algebraic stacks are immersions.
Similarly for closed immersions and open immersions.

\label{lemma-composition-etale}
The composition of two \'etale morphisms of algebraic spaces
is \'etale.

\label{lemma-polarized-diagonal-separated-fp}
The diagonal of $\Polarizedstack$ is separated
and of finite presentation.

\label{lemma-representable-by-spaces-formally-smooth}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is formally smooth on objects, and
\item $p$ is formally smooth (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

statement:
Let $f : Y \to X$ be a morphism of schemes.
\begin{enumerate}
\item The functor $Lf^*$ sends $D_\QCoh(\mathcal{O}_X)$
into $D_\QCoh(\mathcal{O}_Y)$.
\item If $X$ and $Y$ are affine and $f$ is given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[r] & D_\QCoh(\mathcal{O}_Y) \\
D(A) \ar[r] \ar[u]^{- \otimes_A^\mathbf{L} B} &
D_\QCoh(\mathcal{O}_X) \ar[u]_{Lf^*}
}
$$
commutes.
\end{enumerate}

statement_tex:
\label{lemma-quasi-coherence-pullback}
Let $f : Y \to X$ be a morphism of schemes.
\begin{enumerate}
\item The functor $Lf^*$ sends $D_\QCoh(\mathcal{O}_X)$
into $D_\QCoh(\mathcal{O}_Y)$.
\item If $X$ and $Y$ are affine and $f$ is given by the ring map
$A \to B$, then the diagram
$$
\xymatrix{
D(B) \ar[r] & D_\QCoh(\mathcal{O}_Y) \\
D(A) \ar[r] \ar[u]^{- \otimes_A^\mathbf{L} B} &
D_\QCoh(\mathcal{O}_X) \ar[u]_{Lf^*}
}
$$
commutes.
\end{enumerate}

\label{lemma-uniqueness-extension}
Let $f : X \to S$ be a morphism of schemes. Assume $S$ is locally Noetherian
and $f$ locally of finite type. Let $r \geq 0$. Let $\alpha$ and $\beta$
be relative $r$-cycles on $X/S$. The following are equivalent
\begin{enumerate}
\item $\alpha = \beta$, and
\item $\alpha_\eta = \beta_\eta$ for any generic point $\eta \in S$
of an irreducible component of $S$.
\end{enumerate}

statement:
\begin{reference}
\cite[II Theorem 5.6.1(a)]{EGA}
\end{reference}
Let $S$ be a Noetherian scheme.
Let $f : X \to S$ be a separated morphism of finite type.
Then there exist an $n \geq 0$ and a diagram
$$
\xymatrix{
X \ar[rd] & X' \ar[d] \ar[l]^\pi \ar[r] & \mathbf{P}^n_S \ar[dl] \\
& S &
}
$$
where $X' \to \mathbf{P}^n_S$ is an immersion, and
$\pi : X' \to X$ is proper and surjective. Moreover, we may
arrange it such that there exists a dense open subscheme
$U \subset X$ such that $\pi^{-1}(U) \to U$ is an isomorphism.

statement_tex:
\label{lemma-chow-Noetherian}
\begin{reference}
\cite[II Theorem 5.6.1(a)]{EGA}
\end{reference}
Let $S$ be a Noetherian scheme.
Let $f : X \to S$ be a separated morphism of finite type.
Then there exist an $n \geq 0$ and a diagram
$$
\xymatrix{
X \ar[rd] & X' \ar[d] \ar[l]^\pi \ar[r] & \mathbf{P}^n_S \ar[dl] \\
& S &
}
$$
where $X' \to \mathbf{P}^n_S$ is an immersion, and
$\pi : X' \to X$ is proper and surjective. Moreover, we may
arrange it such that there exists a dense open subscheme
$U \subset X$ such that $\pi^{-1}(U) \to U$ is an isomorphism.

\label{lemma-descending-property-quasi-affine}
The property $\mathcal{P}(f) =$``$f$ is quasi-affine''
is fpqc local on the base.

\label{lemma-separated-diagonal-proper}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item $f$ is separated,
\item $\Delta_{X/Y} : X \to X \times_Y X$ is universally closed, and
\item $\Delta_{X/Y} : X \to X \times_Y X$ is proper.
\end{enumerate}

\label{lemma-finite-cohomology}
Let $(\mathcal{C}, \mathcal{O})$ be a ringed site. Let $K$ be an object of
$D(\mathcal{O})$. Let $m \in \mathbf{Z}$.
\begin{enumerate}
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m$, then $H^m(K)$ is a finite type $\mathcal{O}$-module.
\item If $K$ is $m$-pseudo-coherent and $H^i(K) = 0$
for $i > m + 1$, then $H^{m + 1}(K)$ is a finitely presented
$\mathcal{O}$-module.
\end{enumerate}

\label{lemma-resolve}
Let $(A, \text{d})$ be a differential graded algebra.
Let $M$ be a differential graded $A$-module. There exists a homomorphism
$P \to M$ of differential graded $A$-modules such that
\begin{enumerate}
\item $P \to M$ is a quasi-isomorphism, and
\item $P$ has property (P).
\end{enumerate}

\label{lemma-disjoint-union-is-fpqc-covering}
Let $T$ be a scheme. Let $\{f_i : T_i \to T\}_{i \in I}$ be a family of
morphisms of schemes with target $T$. The following are equivalent
\begin{enumerate}
\item $\{f_i : T_i \to T\}_{i \in I}$ is an fpqc covering, and
\item setting $T' = \coprod_{i \in I} T_i$, and $f = \coprod_{i \in I} f_i$
the family $\{f : T' \to T\}$ is an fpqc covering.
\end{enumerate}

\label{lemma-composition-universally-open}
The composition of a pair of (universally) open morphisms of
algebraic stacks is (universally) open.

statement:
There exist an open substack $\Curvesstack^{lci} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{lci}$,
\item $X \to S$ is a local complete intersection morphism, and
\item $X \to S$ is a syntomic morphism.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{lci}$,
\item $X$ is a local complete intersection over $k$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-lci-curves}
There exist an open substack $\Curvesstack^{lci} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors through
$\Curvesstack^{lci}$,
\item $X \to S$ is a local complete intersection morphism, and
\item $X \to S$ is a syntomic morphism.
\end{enumerate}
\item given $X$ a proper scheme over a field $k$ of dimension $\leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{lci}$,
\item $X$ is a local complete intersection over $k$.
\end{enumerate}
\end{enumerate}

\label{lemma-composition-universal-homeomorphism}
The composition of a pair of universal homeomorphisms of
algebraic stacks is a universal homeomorphism.

\label{theorem-picard-group}
For any scheme $X$ we have canonical identifications
\begin{align*}
H_{fppf}^1(X, \mathbf{G}_m) & = H^1_{syntomic}(X, \mathbf{G}_m) \\
& = H^1_{smooth}(X, \mathbf{G}_m) \\
& = H_\etale^1(X, \mathbf{G}_m) \\
& = H^1_{Zar}(X, \mathbf{G}_m) \\
& = \Pic(X) \\
& = H^1(X, \mathcal{O}_X^*)
\end{align*}

statement:
There exist an open substack $\Curvesstack^{nodal} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item $f$ is at-worst-nodal of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item the singularities of $X$ are at-worst-nodal and $X$
is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-nodal-curves}
There exist an open substack $\Curvesstack^{nodal} \subset \Curvesstack$
such that
\begin{enumerate}
\item given a family of curves $f : X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item $f$ is at-worst-nodal of relative dimension $1$,
\end{enumerate}
\item given $X$ a scheme proper over a field $k$ with
$\dim(X) \leq 1$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{nodal}$,
\item the singularities of $X$ are at-worst-nodal and $X$
is equidimensional of dimension $1$.
\end{enumerate}
\end{enumerate}

\label{lemma-reformulate-purity}
Let $(A, \mathfrak m)$ be a Noetherian local ring. Set $X = \Spec(A)$
and let $U = X \setminus \{\mathfrak m\}$.
Let $V$ be finite \'etale
over $U$. Assume $A$ has depth $\geq 2$. The following are equivalent
\begin{enumerate}
\item $V = Y \times_X U$ for some $Y \to X$ finite \'etale,
\item $B = \Gamma(V, \mathcal{O}_V)$ is finite \'etale over $A$.
\end{enumerate}

\label{lemma-ubiquity-excellent}
The following types of schemes are excellent.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\end{enumerate}

\label{lemma-zariski-etale-smooth-syntomic}
Any smooth covering is a syntomic covering, and a fortiori,
any \'etale or Zariski covering is a syntomic covering.

\label{lemma-etale-locally-finite-presentation}
\begin{slogan}
\'Etale implies locally of finite presentation.
\end{slogan}
An \'etale morphism of algebraic spaces is locally of finite presentation.

\label{lemma-action-base-change}
Forming $\alpha \cap \beta$ is compatible with flat base change
and flat pullback (see proof for elucidation).

\label{lemma-composition-integral}
The composition of integral (resp.\ finite) morphisms is integral
(resp.\ finite).

statement:
\begin{reference}
\cite[Lemma 3]{Faltings-annulators}
\end{reference}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $M$ be a finite $A$-module. Let $n \geq 0$.
The following are equivalent
\begin{enumerate}
\item $H^i_T(M)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(M)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(M)$ for $i \leq n$.
\end{enumerate}

statement_tex:
\label{lemma-check-finiteness-local-cohomology-by-annihilator}
\begin{reference}
\cite[Lemma 3]{Faltings-annulators}
\end{reference}
Let $A$ be a Noetherian ring. Let $T \subset \Spec(A)$ be a subset stable
under specialization. Let $M$ be a finite $A$-module. Let $n \geq 0$.
The following are equivalent
\begin{enumerate}
\item $H^i_T(M)$ is finite for $i \leq n$,
\item there exists an ideal $J \subset A$ with $V(J) \subset T$
such that $J$ annihilates $H^i_T(M)$ for $i \leq n$.
\end{enumerate}
If $T = V(I) = Z$ for an ideal $I \subset A$, then these are also
equivalent to
\begin{enumerate}
\item[(3)] there exists an $e \geq 0$ such that $I^e$ annihilates
$H^i_Z(M)$ for $i \leq n$.
\end{enumerate}

\label{lemma-pseudo-torsor-implications}
Let $S$ be a scheme. Let $B$ be an algebraic space over $S$.
Let $G$ be a group algebraic space over $B$.
Let $X$ be a pseudo $G$-torsor over $B$.
Assume $G$ and $X$ locally of finite type over $B$.
\begin{enumerate}
\item If $G \to B$ is unramified, then $X \to B$ is unramified.
\item If $G \to B$ is locally quasi-finite, then $X \to B$ is
locally quasi-finite.
\end{enumerate}

\label{lemma-composition-quasi-finite}
The composition of two morphisms which are locally quasi-finite is
locally quasi-finite. The same is true for quasi-finite morphisms.

\label{lemma-divisor-special-fiber}
Let $X$ be a regular model of a smooth curve $C$ over $K$.
\begin{enumerate}
\item the special fibre $X_k$ is an effective Cartier divisor on $X$,
\item each irreducible component $C_i$ of $X_k$ is an effective
Cartier divisor on $X$,
\item $X_k = \sum m_i C_i$ (sum of effective Cartier divisors)
where $m_i$ is the multiplicity of $C_i$ in $X_k$,
\item $\mathcal{O}_X(X_k) \cong \mathcal{O}_X$.
\end{enumerate}

\label{lemma-closed-immersion-proper}
A closed immersion of algebraic stacks is a proper morphism of
algebraic stacks.

\label{theorem-fundamental-group}
Let $X$ be a connected scheme.
\begin{enumerate}
\item There is a topology on $\pi_1(X, \overline{x})$ such that the open
subgroups form a fundamental system of open nbhds of $e\in \pi_1(X, \overline
x)$.
\item With topology of (1) the group
$\pi_1(X, \overline{x})$ is a profinite group.
\item The functor
$$
\begin{matrix}
\text{ schemes finite } \atop \text{ \'etale over }X & \to &
\text{ finite discrete continuous } \atop \pi_1(X, \overline{x})\text{-sets}\\
Y / X& \mapsto & F_{\overline{x}}(Y) \text{ with its natural action}
\end{matrix}
$$
is an equivalence of categories.
\end{enumerate}

statement:
Let $p: \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. Consider a diagram of $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d]_a & x_\epsilon \ar[d]_e \\
x \ar[r]^d        & x_0
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A \times_k k[\epsilon] \ar[r] \ar[d] & k[\epsilon] \ar[d] \\
A \ar[r] & k.
}
}
$$
in $\mathcal{C}_\Lambda$. Assume $\mathcal{F}$ satisfies (S2).
Then there exists a morphism $s : x \to y$ with $a \circ s = \text{id}_x$
if and only if there exists a morphism $s_\epsilon : x \to x_\epsilon$
with $e \circ s_\epsilon = d$.

statement_tex:
\label{lemma-lifting-section}
Let $p: \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. Consider a diagram of $\mathcal{F}$
$$
\vcenter{
\xymatrix{
y \ar[r] \ar[d]_a & x_\epsilon \ar[d]_e \\
x \ar[r]^d        & x_0
}
}
\quad\text{lying over}\quad
\vcenter{
\xymatrix{
A \times_k k[\epsilon] \ar[r] \ar[d] & k[\epsilon] \ar[d] \\
A \ar[r] & k.
}
}
$$
in $\mathcal{C}_\Lambda$. Assume $\mathcal{F}$ satisfies (S2).
Then there exists a morphism $s : x \to y$ with $a \circ s = \text{id}_x$
if and only if there exists a morphism $s_\epsilon : x \to x_\epsilon$
with $e \circ s_\epsilon = d$.

\label{lemma-descending-property-flat}
The property $\mathcal{P}(f) =$``$f$ is flat''
is fpqc local on the base.

\label{lemma-locally-finite-presentation-universally-open}
Let $f : X \to S$ be a morphism.
\begin{enumerate}
\item If $f$ is locally of finite presentation and generalizations lift
along $f$, then $f$ is open.
\item If $f$ is locally of finite presentation and generalizations lift
along every base change of $f$, then $f$ is universally open.
\end{enumerate}

\label{lemma-characterize-perfect}
Let $\Lambda$ be a left Noetherian ring and $K\in D(\Lambda)$. Then $K$ is
perfect if and only if the two following conditions hold:
\begin{enumerate}
\item
$K$ has finite $\text{Tor}$-dimension, and
\item
for all $i \in \mathbf{Z}$, $H^i(K)$ is a finite $\Lambda$-module.
\end{enumerate}

\label{lemma-continuous-representations-RS}
Example \ref{example-continuous-representations}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{V, \rho_0}$ is a deformation category
for any finite dimensional continuous representation
$\rho_0 : \Gamma \to \text{GL}_k(V)$.

\label{lemma-epi-not-surjective}
