\label{proposition-compact}
Let $(A, \text{d})$ be a differential graded algebra. Let $E$ be an
object of $D(A, \text{d})$. Then the following are equivalent
\begin{enumerate}
\item $E$ is a compact object,
\item $E$ is a direct summand of an object of $D(A, \text{d})$
which is represented by a differential graded module $P$ which
has a finite filtration $F_\bullet$ by differential graded submodules
such that $F_iP/F_{i - 1}P$ are finite direct sums of shifts of $A$.
\end{enumerate}

\label{lemma-characterize-Cohen-Macaulay}
Let $X$ be a scheme. The following are equivalent:
\begin{enumerate}
\item $X$ is Cohen-Macaulay,
\item $X$ is locally Noetherian and all of its local rings are Cohen-Macaulay,
and
\item $X$ is locally Noetherian and for any closed point $x \in X$
the local ring $\mathcal{O}_{X, x}$ is Cohen-Macaulay.
\end{enumerate}

\label{lemma-smooth}
Let $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\underline{R}|_{\mathcal{C}_\Lambda}$ is smooth,
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology,
\item $\Lambda \to R$ is flat and $R \otimes_\Lambda k'$ is
geometrically regular over $k'$, and
\item $\Lambda \to R$ is flat and $k' \to R \otimes_\Lambda k'$ is
formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case, these are also equivalent to
\begin{enumerate}
\item[(5)] $R$ is isomorphic to $\Lambda[[x_1, \ldots, x_n]]$
for some $n$.
\end{enumerate}

