\label{lemma-maximal-subfield-splits}
A maximal subfield of a finite central skew field $K$ over $k$ is
a splitting field for $K$.

\label{lemma-dimension}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following quantities are equal:
\begin{enumerate}
\item The dimension of $X$.
\item The supremum of the dimensions of the local rings of $X$.
\item The supremum of $\dim_x(X)$ for $x \in |X|$.
\end{enumerate}

\label{lemma-contained-in}
Any set of big Zariski sites is contained in a common big Zariski site.
The same is true, mutatis mutandis, for big fppf and big \'etale sites.

\label{lemma-category-fibred}
Let $X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item The category $\mathcal{C}_{X/Y}$ is fibred over $X_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over $Y_{Zar}$.
\item The category $\mathcal{C}_{X/Y}$ is fibred over the
category of pairs $(U, V)$ where $U \subset X$, $V \subset Y$ are
open and $f(U) \subset V$.
\end{enumerate}

\label{lemma-reduced-space}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
The following are equivalent
\begin{enumerate}
\item $X$ is reduced,
\item for every $x \in |X|$ the local ring of $X$ at $x$ is
reduced (Remark \ref{remark-list-properties-local-ring-local-etale-topology}).
\end{enumerate}
In this case $\Gamma(X, \mathcal{O}_X)$ is a reduced ring and
if $f \in \Gamma(X, \mathcal{O}_X)$ has $X = V(f)$, then $f = 0$.

