\label{lemma-curves-limits}
The stack $\Curvesstack \to \Sch_{fppf}$ is limit preserving
(Artin's Axioms, Definition \ref{artin-definition-limit-preserving}).

\label{lemma-exactness-pushforward-pullback}
Let $f : (\Sh(\mathcal{C}), \mathcal{O}_\mathcal{C})
\to (\Sh(\mathcal{D}), \mathcal{O}_\mathcal{D})$
be a morphism of ringed topoi.
\begin{enumerate}
\item The functor $f_*$ is left exact. In fact it commutes with
all limits.
\item The functor $f^*$ is right exact. In fact it commutes
with all colimits.
\end{enumerate}

\label{lemma-etale-formally-etale}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
The following are equivalent:
\begin{enumerate}
\item The morphism $f$ is \'etale, and
\item the morphism $f$ is locally of finite presentation and
formally \'etale.
\end{enumerate}

\label{lemma-Noetherian-h-covering}
Let $X$ be a Noetherian scheme. Let $\{X_i \to X\}_{i \in I}$
be a finite family of finite type morphisms. The following are equivalent
\begin{enumerate}
\item $\coprod_{i \in I} X_i \to X$ is universally submersive
(Morphisms, Definition
\ref{morphisms-definition-submersive}), and
\item $\{X_i \to X\}_{i \in I}$ is an h covering.
\end{enumerate}

\label{lemma-mono-towards-locally-quasi-finite-over-field}
Let $k$ be a field. Let $f : X \to Y$ be a monomorphism of algebraic spaces
over $k$. If $Y$ is locally quasi-finite over $k$ so is $X$.

\label{lemma-base-change-etale}
The base change of an \'etale morphism of algebraic spaces
by any morphism of algebraic spaces is \'etale.

