\label{lemma-immersion-locally-finite-type}
A closed immersion is of finite type.
An immersion is locally of finite type.

\label{lemma-zariski-etale-smooth-syntomic-fppf}
Any syntomic covering is an fppf covering, and a fortiori,
any smooth, \'etale, or Zariski covering is an fppf covering.

\label{lemma-deform}
Let $S$ be a scheme. Let $(f, f') : (X \subset X') \to (Y \subset Y')$ be a
morphism of first order thickenings of algebraic spaces over $S$. Assume that
$f$ is flat. Then the following are equivalent
\begin{enumerate}
\item $f'$ is flat and $X = Y \times_{Y'} X'$, and
\item the canonical map $f^*\mathcal{C}_{Y/Y'} \to \mathcal{C}_{X/X'}$
is an isomorphism.
\end{enumerate}

\label{lemma-functor-quasi-coherent-from-affine}
Let $R$ be a ring. Let $X$ and $Y$ be schemes over $R$ with $X$ affine.
There is an equivalence of categories between
\begin{enumerate}
\item the category of $R$-linear functors
$F : \QCoh(\mathcal{O}_X) \to \QCoh(\mathcal{O}_Y)$
which are right exact and commute with arbitrary direct sums, and
\item the category $\QCoh(\mathcal{O}_{X \times_R Y})$
\end{enumerate}
given by sending $\mathcal{K}$ to the functor $F$ in (\ref{equation-FM-QCoh}).

statement:
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
\begin{enumerate}
\item If $|X|$ is a singleton then $X$ is a scheme.
\item If $|X|$ is a singleton and $X$ is reduced, then
$X \cong \Spec(k)$ for some field $k$.
\end{enumerate}

statement_tex:
\label{lemma-when-field}
Let $S$ be a scheme. Let $X$ be a decent algebraic space over $S$.
\begin{enumerate}
\item If $|X|$ is a singleton then $X$ is a scheme.
\item If $|X|$ is a singleton and $X$ is reduced, then
$X \cong \Spec(k)$ for some field $k$.
\end{enumerate}

\label{lemma-pullback-effective-Cartier-defined}
Let $S$ be a scheme.
Let $f : X \to Y$ be a morphism of algebraic spaces over $S$.
Let $D \subset Y$ be an effective Cartier divisor.
The pullback of $D$ by $f$ is defined in each of the following cases:
\begin{enumerate}
\item $f(x) \not \in |D|$ for any weakly associated point $x$ of $X$,
\item $f$ is flat, and
\item add more here as needed.
\end{enumerate}

statement:
\begin{reference}
\cite[Expose VIII, Corollaire 4.3]{SGA1} and
\cite[IV, Corollaire 2.3.12]{EGA}
\end{reference}
Let $f : X \to Y$ be a quasi-compact, surjective, flat morphism.
A subset $T \subset Y$ is open (resp.\ closed) if and only
$f^{-1}(T)$ is open (resp.\ closed). In other words, $f$ is
a submersive morphism.

statement_tex:
\label{lemma-fpqc-quotient-topology}
\begin{reference}
\cite[Expose VIII, Corollaire 4.3]{SGA1} and
\cite[IV, Corollaire 2.3.12]{EGA}
\end{reference}
Let $f : X \to Y$ be a quasi-compact, surjective, flat morphism.
A subset $T \subset Y$ is open (resp.\ closed) if and only
$f^{-1}(T)$ is open (resp.\ closed). In other words, $f$ is
a submersive morphism.

\label{lemma-split-universally-exact-sequence}
Let $A$ be a ring.
\begin{enumerate}
\item Let $L \to M \to N$ be a universally exact sequence
of $A$-modules. Let $K = \Im(M \to N)$.
Then $K \to N$ is universally injective.
\item Any universally exact complex
can be split into universally exact short exact sequences.
\end{enumerate}

\label{lemma-refine-by-standard-ph}
Let $T$ be an affine scheme. Each of the following types of families
of maps with target $T$ has a refinement by a standard ph covering:
\begin{enumerate}
\item any Zariski open covering of $T$,
\item $\{W_{ji} \to T\}_{j = 1, \ldots, m, i = 1, \ldots n_j}$
where $\{W_{ji} \to U_j\}_{i = 1, \ldots, n_j}$
and $\{U_j \to T\}_{j = 1, \ldots, m}$ are standard ph coverings.
\end{enumerate}

\label{lemma-surjective}
Let $A \to B$ be a ring map in $\mathcal{C}_\Lambda$.
The following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $\mathfrak m_A/\mathfrak m_A^2 \to \mathfrak m_B/\mathfrak m_B^2$
is surjective, and
\item $\mathfrak m_A/(\mathfrak m_\Lambda A + \mathfrak m_A^2)
\to \mathfrak m_B/(\mathfrak m_\Lambda B + \mathfrak m_B^2)$ is surjective.
\end{enumerate}

\label{lemma-flat-surjective-monomorphism}
A quasi-compact flat surjective monomorphism of algebraic spaces
is an isomorphism.

\label{lemma-representable-by-spaces-surjective}
Let $p : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of categories
fibred in groupoids over $(\Sch/S)_{fppf}$. If $p$ is
representable by algebraic spaces, then the following are equivalent:
\begin{enumerate}
\item $p$ is surjective on objects, and
\item $p$ is surjective (see
Algebraic Stacks,
Definition \ref{algebraic-definition-relative-representable-property}).
\end{enumerate}

