statement:
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under composition of morphisms.

statement_tex:
\label{lemma-composition-separated}
All of the separation axioms listed in
Definition \ref{definition-separated}
are stable under composition of morphisms.

\label{lemma-base-change-finite-type}
A base change of a finite type morphism is finite type.
The same holds for locally of finite type.

\label{lemma-regular-gorenstein}
A regular local ring is Gorenstein.
A regular ring is Gorenstein.

\label{lemma-special-locally-free}
Any of the properties (1) -- (8) of Definition \ref{definition-site-local}
is intrinsic (see discussion in Section \ref{section-intrinsic}).

\label{lemma-descending-property-etale}
The property $\mathcal{P}(f) =$``$f$ is \'etale''
is fpqc local on the base.

\label{lemma-locally-closed-where-H0-locally-free}
Let $X$ be a scheme. Let $E \in D(\mathcal{O}_X)$ be perfect
of tor-amplitude in $[a, b]$ for some $a, b \in \mathbf{Z}$.
Let $r \geq 0$.
Then there exists a locally closed subscheme $j : Z \to X$
characterized by the following
\begin{enumerate}
\item $H^a(Lj^*E)$ is a locally free $\mathcal{O}_Z$-module of rank $r$, and
\item a morphism $f : Y \to X$ factors through $Z$
if and only if for all morphisms $g : Y' \to Y$ the
$\mathcal{O}_{Y'}$-module $H^a(L(f \circ g)^*E)$ is locally free
of rank $r$.
\end{enumerate}
Moreover, $j : Z \to X$ is of finite presentation and we have
\begin{enumerate}
\item[(3)] if $f : Y \to X$ factors as $Y \xrightarrow{g} Z \to X$, then
$H^a(Lf^*E) = g^*H^a(Lj^*E)$,
\item[(4)] if $\beta_a(x) \leq r$ for all $x \in X$, then
$j$ is a closed immersion and given $f : Y \to X$ the following
are equivalent
\begin{enumerate}
\item $f : Y \to X$ factors through $Z$,
\item $H^a(Lf^*E)$ is a locally free $\mathcal{O}_Y$-module of rank $r$,
\end{enumerate}
and if $r = 1$ these are also equivalent to
\begin{enumerate}
\item[(c)] $\mathcal{O}_Y \to \SheafHom_{\mathcal{O}_Y}(H^a(Lf^*E), H^a(Lf^*E))$
is injective.
\end{enumerate}
\end{enumerate}

\label{lemma-pseudo-coherent-hocolim}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $K \in D(\mathcal{O}_X)$. The following are equivalent
\begin{enumerate}
\item $K$ is pseudo-coherent, and
\item $K = \text{hocolim} K_n$ where
$K_n$ is perfect and $\tau_{\geq -n}K_n \to \tau_{\geq -n}K$
is an isomorphism for all $n$.
\end{enumerate}

\label{lemma-countable}
Let $(A, \text{d})$ be a differential graded algebra with
$H^i(A)$ countable for each $i$. Let $M$ be an object of $D(A, \text{d})$.
Then the following are equivalent
\begin{enumerate}
\item $M = \text{hocolim} E_n$ with $E_n$ compact in $D(A, \text{d})$, and
\item $H^i(M)$ is countable for each $i$.
\end{enumerate}

\label{lemma-gorenstein-shriek}
Let $\varphi : R \to A$ be a flat finite type homomorphism of Noetherian rings.
The following are equivalent
\begin{enumerate}
\item the fibres $A \otimes_R \kappa(\mathfrak p)$ are Gorenstein
for all primes $\mathfrak p \subset R$, and
\item $\omega_{A/R}^\bullet$ is an invertible object of $D(A)$, see
More on Algebra, Lemma \ref{more-algebra-lemma-invertible-derived}.
\end{enumerate}

\label{lemma-shriek-boundedness}
Let $\varphi : R \to A$ be a finite type homomorphism of Noetherian rings.
\begin{enumerate}
\item $\varphi^!$ maps $D^+(R)$ into $D^+(A)$ and
$D^+_{\textit{Coh}}(R)$ into $D^+_{\textit{Coh}}(A)$.
\item if $\varphi$ is perfect, then $\varphi^!$ maps
$D^-(R)$ into $D^-(A)$,
$D^-_{\textit{Coh}}(R)$ into $D^-_{\textit{Coh}}(A)$, and
$D^b_{\textit{Coh}}(R)$ into $D^b_{\textit{Coh}}(A)$.
\end{enumerate}

\label{lemma-formally-etale-nontrivial-cotangent-complex}
There exists a formally \'etale surjective ring map $A \to B$
with $L_{B/A}$ not equal to zero.

\label{lemma-smooth-smooth-local-source}
The property $\mathcal{P}(f)=$``$f$ is smooth''
is smooth local on the source.

\label{lemma-when-scheme-after-base-change}
Let $k$ be a field with algebraic closure $\overline{k}$.
Let $X$ be a quasi-separated algebraic space over $k$.
\begin{enumerate}
\item If there exists a field extension $K/k$ such that
$X_K$ is a scheme, then $X_{\overline{k}}$ is a scheme.
\item If $X$ is quasi-compact and there exists a field extension
$K/k$ such that $X_K$ is a scheme, then $X_{k'}$
is a scheme for some finite separable extension $k'$ of $k$.
\end{enumerate}

\label{lemma-quasi-compact-quasi-separated-permanence}
Let $f : \mathcal{X} \to \mathcal{Y}$ be a morphism of algebraic stacks.
\begin{enumerate}
\item If $\mathcal{X}$ is quasi-compact and $\mathcal{Y}$ is
quasi-separated, then $f$ is quasi-compact.
\item If $\mathcal{X}$ is quasi-compact and quasi-separated and $\mathcal{Y}$
is quasi-separated, then $f$ is quasi-compact and quasi-separated.
\item A fibre product of quasi-compact and quasi-separated algebraic stacks
is quasi-compact and quasi-separated.
\end{enumerate}

\label{lemma-monomorphism-separated}
A monomorphism of algebraic stacks is separated and DM.
The same is true for immersions of algebraic stacks.

