\label{lemma-injective-module-divide}
Let $R$ be a Noetherian ring. Let $I$ be an injective $R$-module.
\begin{enumerate}
\item Let $f \in R$. Then $E = \bigcup I[f^n] = I[f^\infty]$
is an injective submodule of $I$.
\item Let $J \subset R$ be an ideal. Then the $J$-power torsion
submodule $I[J^\infty]$ is an injective submodule of $I$.
\end{enumerate}

\label{lemma-groupoid-in-functors-prorep-equivalences}
Let $(U, R, s, t, c)$ be a groupoid in functors on $\mathcal{C}_\Lambda$.
\begin{enumerate}
\item $(U, R, s, t, c)$ is prorepresentable if and only if its completion is
representable as a groupoid in functors on $\widehat{\mathcal{C}}_\Lambda$.
\item $(U, R, s, t, c)$ is prorepresentable if and only if $U$ and $R$ are
prorepresentable.
\end{enumerate}

\label{lemma-CLambdahat-coproducts}
The category $\widehat{\mathcal{C}}_\Lambda$ admits coproducts
of pairs of objects.

statement:
\begin{reference}
\cite[IV Corollary 12.1.7(iii)]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. Let
$$
W = \{x \in X \mid f\text{ is Cohen-Macaulay at }x\}
$$
Then
\begin{enumerate}
\item $W = \{x \in X \mid \mathcal{O}_{X_{f(x)}, x}\text{ is Cohen-Macaulay}\}$,
\item $W$ is open in $X$,
\item $W$ is dense in every fibre of $X \to S$,
\item the formation of $W$ commutes with arbitrary base change of $f$:
For any morphism $g : S' \to S$, consider
the base change $f' : X' \to S'$ of $f$ and the
projection $g' : X' \to X$. Then the corresponding
set $W'$ for the morphism $f'$ is equal to $W' = (g')^{-1}(W)$.
\end{enumerate}

statement_tex:
\label{lemma-flat-finite-presentation-CM-open}
\begin{reference}
\cite[IV Corollary 12.1.7(iii)]{EGA}
\end{reference}
Let $f : X \to S$ be a morphism of schemes which is flat and locally
of finite presentation. Let
$$
W = \{x \in X \mid f\text{ is Cohen-Macaulay at }x\}
$$
Then
\begin{enumerate}
\item $W = \{x \in X \mid \mathcal{O}_{X_{f(x)}, x}\text{ is Cohen-Macaulay}\}$,
\item $W$ is open in $X$,
\item $W$ is dense in every fibre of $X \to S$,
\item the formation of $W$ commutes with arbitrary base change of $f$:
For any morphism $g : S' \to S$, consider
the base change $f' : X' \to S'$ of $f$ and the
projection $g' : X' \to X$. Then the corresponding
set $W'$ for the morphism $f'$ is equal to $W' = (g')^{-1}(W)$.
\end{enumerate}

\label{lemma-quasi-regular-immersion}
Let $S$ be a scheme. Let $i : Z \to X$ be an immersion of algebraic spaces
over $S$. Then $i$ is a quasi-regular immersion if and only if the following
conditions are satisfied
\begin{enumerate}
\item $i$ is locally of finite presentation,
\item the conormal sheaf $\mathcal{C}_{Z/X}$ is finite locally free, and
\item the map (\ref{equation-conormal-algebra-quotient}) is an isomorphism.
\end{enumerate}

\label{lemma-exterior-product-well-defined-dim-1}
The map $\times : \CH_n(X) \otimes_{\mathbf{Z}} \CH_m(Y) \to
\CH_{n + m - 1}(X \times_S Y)$ is well defined.

\label{lemma-comparison-fppf-etale}
Let $S$ be a scheme. Let $X$ be an algebraic space over $S$.
\begin{enumerate}
\item For $\mathcal{F} \in \Sh(X_\etale)$ we have
$\epsilon_{X, *}a_X^{-1}\mathcal{F} = \pi_X^{-1}\mathcal{F}$
and $a_{X, *}a_X^{-1}\mathcal{F} = \mathcal{F}$.
\item For $\mathcal{F} \in \textit{Ab}(X_\etale)$ we have
$R^i\epsilon_{X, *}(a_X^{-1}\mathcal{F}) = 0$ for $i > 0$.
\end{enumerate}

\label{lemma-bounded-truncation}
Let $X$ be a quasi-compact and quasi-separated scheme.
Let $P \in D_{perf}(\mathcal{O}_X)$ and $E \in D_{\QCoh}(\mathcal{O}_X)$. 
Let $a \in \mathbf{Z}$. The following are equivalent
\begin{enumerate}
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], E) = 0$ for $i \gg 0$, and
\item $\Hom_{D(\mathcal{O}_X)}(P[-i], \tau_{\geq a} E) = 0$ for $i \gg 0$.
\end{enumerate}

statement:
Let $X$ be a scheme such that any quasi-compact open has a finite number
of irreducible components. The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of normal integral schemes.
\end{enumerate}

statement_tex:
\label{lemma-normal-locally-finite-nr-irreducibles}
Let $X$ be a scheme such that any quasi-compact open has a finite number
of irreducible components. The following are equivalent:
\begin{enumerate}
\item $X$ is normal, and
\item $X$ is a disjoint union of normal integral schemes.
\end{enumerate}

statement:
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
The following are equivalent
\begin{enumerate}
\item $B$ is Gorenstein, and
\item $A$ and $B/\mathfrak m_A B$ are Gorenstein.
\end{enumerate}

statement_tex:
\label{lemma-flat-under-gorenstein}
Let $A \to B$ be a flat local homomorphism of Noetherian local rings.
The following are equivalent
\begin{enumerate}
\item $B$ is Gorenstein, and
\item $A$ and $B/\mathfrak m_A B$ are Gorenstein.
\end{enumerate}

\label{lemma-algebraic-morphism-to-algebraic}
Let $S$ be a scheme.
Let $F : \mathcal{X} \to \mathcal{Y}$ be a $1$-morphism of
stacks in groupoids over $(\Sch/S)_{fppf}$. If
\begin{enumerate}
\item $\mathcal{Y}$ is an algebraic stack, and
\item $F$ is algebraic (see above),
\end{enumerate}
then $\mathcal{X}$ is an algebraic stack.

